const dialogueQuestions = [
  {
    id: 1, category: "school", title: "Planning the School Festival",
    dialogue: [
      { speaker: "Mika", text: "Hi, Ryan. Do you have a minute?", ja: "こんにちは、ライアン。少し時間ある？" },
      { speaker: "Ryan", blank: "a" },
      { speaker: "Mika", text: "Our class needs to decide what to do for the school festival.", ja: "私たちのクラスで、文化祭に何をするか決める必要があるの。" },
      { speaker: "Ryan", text: "I see. Have you come up with any ideas?", ja: "なるほど。何か案は出た？" },
      { speaker: "Mika", text: "We have two ideas. One is to run a small café, and the other is to sell handmade goods.", ja: "案が2つあるの。1つは小さなカフェを開くことで、もう1つは手作りの商品を売ることよ。" },
      { speaker: "Ryan", blank: "b" },
      { speaker: "Ryan", text: "A café might need more people and equipment.", ja: "カフェのほうが、より多くの人手や設備が必要かもしれないね。" },
      { speaker: "Mika", text: "That’s true. However, many students in our class like cooking.", ja: "そうね。でも、私たちのクラスには料理が好きな生徒がたくさんいるの。" },
      { speaker: "Ryan", text: "Then, why don’t you ask everyone which idea they prefer?", ja: "それなら、みんなにどちらの案がよいか聞いてみたら？" },
      { speaker: "Mika", blank: "c" },
      { speaker: "Mika", text: "We can take a vote during tomorrow’s homeroom.", ja: "明日のホームルームで投票できるわ。" },
      { speaker: "Ryan", text: "Good. You should also find out how much each plan will cost.", ja: "いいね。それぞれの計画にどれくらい費用がかかるかも調べたほうがいいよ。" },
      { speaker: "Mika", text: "You’re right.", ja: "そうね。" },
      { speaker: "Mika", blank: "d" },
      { speaker: "Ryan", text: "Mr. Brown may know because he helped with the festival last year.", ja: "ブラウン先生なら知っているかもしれないよ。去年、文化祭の手伝いをしていたから。" },
      { speaker: "Mika", text: "That’s a good point. I’ll talk to him after school.", ja: "それはいい考えね。放課後に先生に話してみるわ。" },
      { speaker: "Ryan", text: "Great.", ja: "いいね。" },
      { speaker: "Ryan", blank: "e" },
      { speaker: "Mika", text: "Thanks, Ryan. I hope everyone enjoys preparing for the festival.", ja: "ありがとう、ライアン。みんなが文化祭の準備を楽しんでくれるといいな。" }
    ],
    choices: [
      { id: "c1", text: "That sounds like a fair way to decide.", ja: "それは公平な決め方のようだね。" },
      { id: "c2", text: "What do you want to talk about?", ja: "何について話したいの？" },
      { id: "c3", text: "I’ll help you if you need anything.", ja: "何か必要なことがあれば手伝うよ。" },
      { id: "c4", text: "I wonder which one will be easier to prepare.", ja: "どちらのほうが準備しやすいのかな。" },
      { id: "c5", text: "Do you know who I should ask about the budget?", ja: "予算について誰に聞けばよいか知っている？" },
      { id: "c6", text: "We could ask another class what they are planning.", ja: "ほかのクラスが何を計画しているか聞いてみることもできるね。" }
    ],
    answers: { a: "c2", b: "c4", c: "c1", d: "c5", e: "c3" }
  },

  {
    id: 2, category: "service", title: "Checking In at a Hotel",
    dialogue: [
      { speaker: "Clerk", text: "Good afternoon. How can I help you?", ja: "こんにちは。どのようなご用件でしょうか。" },
      { speaker: "Guest", text: "Hi. I have a reservation under the name of Daniel Lee.", ja: "こんにちは。ダニエル・リーという名前で予約しています。" },
      { speaker: "Clerk", text: "Let me check. Yes, Mr. Lee.", ja: "確認いたします。はい、リー様。" },
      { speaker: "Clerk", blank: "a" },
      { speaker: "Guest", text: "Thank you. Is breakfast included in the room price?", ja: "ありがとうございます。朝食は宿泊料金に含まれていますか。" },
      { speaker: "Clerk", text: "Yes. Breakfast is served in the restaurant from six thirty to nine thirty.", ja: "はい。朝食は午前6時30分から9時30分までレストランで提供しております。" },
      { speaker: "Guest", text: "Great.", ja: "よかったです。" },
      { speaker: "Guest", blank: "b" },
      { speaker: "Clerk", text: "It’s on the first floor, next to the front desk.", ja: "1階のフロントの隣にございます。" },
      { speaker: "Guest", text: "I see. Also, I have an online meeting early tomorrow morning. Is there a quiet place where I can work?", ja: "分かりました。それから、明日の早朝にオンライン会議があります。静かに仕事ができる場所はありますか。" },
      { speaker: "Clerk", text: "Certainly.", ja: "もちろんです。" },
      { speaker: "Clerk", blank: "c" },
      { speaker: "Clerk", text: "It is open twenty-four hours a day.", ja: "そこは24時間開いております。" },
      { speaker: "Guest", text: "That sounds perfect. Do I need to make a reservation?", ja: "それはちょうどよいです。予約する必要はありますか。" },
      { speaker: "Clerk", text: "No, but it can become crowded in the evening.", ja: "いいえ。ただし、夕方には混雑することがあります。" },
      { speaker: "Guest", blank: "d" },
      { speaker: "Guest", text: "I’ll probably use it around seven tomorrow morning.", ja: "おそらく明日の朝7時ごろに使います。" },
      { speaker: "Clerk", text: "Then you should have no trouble finding a seat.", ja: "それでしたら、席を見つけるのに困ることはないでしょう。" },
      { speaker: "Guest", text: "Thank you for your help.", ja: "ご親切にありがとうございます。" },
      { speaker: "Clerk", text: "You’re welcome.", ja: "どういたしまして。" },
      { speaker: "Clerk", blank: "e" },
      { speaker: "Guest", text: "Thanks. I’m looking forward to my stay.", ja: "ありがとうございます。滞在を楽しみにしています。" }
    ],
    choices: [
      { id: "c1", text: "Where can I find the restaurant?", ja: "レストランはどこにありますか。" },
      { id: "c2", text: "Please enjoy your stay with us.", ja: "どうぞ当ホテルでの滞在をお楽しみください。" },
      { id: "c3", text: "We have a business room on the second floor.", ja: "2階にビジネスルームがございます。" },
      { id: "c4", text: "Here is your room key. You’ll be in Room 408.", ja: "こちらが客室の鍵です。408号室でございます。" },
      { id: "c5", text: "In that case, it shouldn’t be a problem.", ja: "それなら、問題はなさそうです。" },
      { id: "c6", text: "Does the hotel offer room service in the evening?", ja: "このホテルでは、夕方にルームサービスを利用できますか。" }
    ],
    answers: { a: "c4", b: "c1", c: "c3", d: "c5", e: "c2" }
  },

  {
    id: 3, category: "business", title: "Website Project Delay",
    dialogue: [
      { speaker: "Ms. Clark", text: "Good morning, Ben. How is the new website project going?", ja: "おはよう、ベン。新しいウェブサイトのプロジェクトはどうですか。" },
      { speaker: "Ben", text: "We’ve made good progress, but there is one problem.", ja: "順調に進んでいますが、1つ問題があります。" },
      { speaker: "Ms. Clark", blank: "a" },
      { speaker: "Ben", text: "The design team needs more time to finish the main page.", ja: "デザインチームがメインページを完成させるために、もう少し時間を必要としています。" },
      { speaker: "Ms. Clark", text: "I thought they were going to finish it by Friday.", ja: "金曜日までに完成させる予定だったと思っていました。" },
      { speaker: "Ben", text: "They were, but the client asked them to change several parts of the design.", ja: "その予定でしたが、顧客がデザインのいくつかの部分を変更するよう求めたのです。" },
      { speaker: "Ms. Clark", text: "I see.", ja: "なるほど。" },
      { speaker: "Ms. Clark", blank: "b" },
      { speaker: "Ben", text: "They said they would need three more days.", ja: "あと3日必要だと言っています。" },
      { speaker: "Ms. Clark", text: "That may affect our testing schedule.", ja: "それは私たちのテストの日程に影響するかもしれませんね。" },
      { speaker: "Ben", text: "Yes.", ja: "はい。" },
      { speaker: "Ben", blank: "c" },
      { speaker: "Ben", text: "We could start testing the other pages first.", ja: "先にほかのページのテストを始めることもできます。" },
      { speaker: "Ms. Clark", text: "That’s a good idea. We don’t have to wait until the entire website is finished.", ja: "それはいい考えです。ウェブサイト全体が完成するまで待つ必要はありません。" },
      { speaker: "Ben", text: "I’ll speak with the testing team this afternoon.", ja: "今日の午後、テストチームと話します。" },
      { speaker: "Ms. Clark", text: "Please do. Also, make sure the client knows about the new schedule.", ja: "お願いします。それから、新しい日程を顧客に必ず知らせてください。" },
      { speaker: "Ben", blank: "d" },
      { speaker: "Ben", text: "I’ll send them an updated plan before lunch.", ja: "昼食前に更新した計画を送ります。" },
      { speaker: "Ms. Clark", text: "Excellent.", ja: "すばらしい。" },
      { speaker: "Ms. Clark", blank: "e" },
      { speaker: "Ben", text: "Thank you. I’ll let you know if anything else changes.", ja: "ありがとうございます。ほかに何か変更があればお知らせします。" }
    ],
    choices: [
      { id: "c1", text: "How much extra time do they need?", ja: "追加でどれくらいの時間が必要なのですか。" },
      { id: "c2", text: "What seems to be the problem?", ja: "どのような問題があるのですか。" },
      { id: "c3", text: "Has the client approved the new colors yet?", ja: "顧客は新しい配色をもう承認しましたか。" },
      { id: "c4", text: "But we may be able to avoid a long delay.", ja: "しかし、大幅な遅れは避けられるかもしれません。" },
      { id: "c5", text: "Of course. I’ll contact them right away.", ja: "もちろんです。すぐに連絡します。" },
      { id: "c6", text: "I’m sure you’ll handle it well.", ja: "あなたなら、きっとうまく対処できるでしょう。" }
    ],
    answers: { a: "c2", b: "c1", c: "c4", d: "c5", e: "c6" }
  },

  {
    id: 4, category: "health", title: "Using a Phone at Night",
    dialogue: [
      { speaker: "Anna", text: "Hi, Leo. You look tired today.", ja: "こんにちは、レオ。今日は疲れているように見えるね。" },
      { speaker: "Leo", text: "I didn’t sleep very well last night.", ja: "昨夜、あまりよく眠れなかったんだ。" },
      { speaker: "Anna", blank: "a" },
      { speaker: "Leo", text: "I kept checking messages on my phone until almost two in the morning.", ja: "午前2時近くまで、ずっとスマートフォンのメッセージを確認していたんだ。" },
      { speaker: "Anna", text: "That’s probably why you couldn’t sleep.", ja: "たぶん、それが眠れなかった理由ね。" },
      { speaker: "Leo", text: "I know, but I always feel that I have to reply immediately.", ja: "分かっているんだけど、いつもすぐに返信しなければならないような気がするんだ。" },
      { speaker: "Anna", blank: "b" },
      { speaker: "Anna", text: "Most messages can wait until the next morning.", ja: "ほとんどのメッセージは、翌朝まで待っても大丈夫よ。" },
      { speaker: "Leo", text: "You’re right. I suppose it has become a bad habit.", ja: "そのとおりだね。悪い習慣になってしまったんだと思う。" },
      { speaker: "Anna", text: "Why don’t you leave your phone in another room when you go to bed?", ja: "寝るとき、スマートフォンを別の部屋に置いたらどう？" },
      { speaker: "Leo", blank: "c" },
      { speaker: "Leo", text: "Then I wouldn’t be able to reach it so easily.", ja: "そうすれば、簡単には手が届かなくなるね。" },
      { speaker: "Anna", text: "Exactly. You could also turn off notifications after ten.", ja: "そのとおり。それから、10時以降は通知を切ることもできるよ。" },
      { speaker: "Leo", text: "That might help, too.", ja: "それも役に立つかもしれない。" },
      { speaker: "Leo", blank: "d" },
      { speaker: "Anna", text: "It may feel strange at first, but you’ll probably get used to it.", ja: "最初は変な感じがするかもしれないけれど、おそらく慣れるよ。" },
      { speaker: "Leo", text: "I hope so. I really need more sleep.", ja: "そうだといいな。本当にもっと睡眠が必要だよ。" },
      { speaker: "Anna", blank: "e" },
      { speaker: "Leo", text: "Thanks. I’ll try your suggestions tonight.", ja: "ありがとう。今夜、君の提案を試してみるよ。" }
    ],
    choices: [
      { id: "c1", text: "What kept you awake?", ja: "何のせいで眠れなかったの？" },
      { id: "c2", text: "That sounds like a good idea.", ja: "それはよい考えだね。" },
      { id: "c3", text: "You don’t need to answer every message right away.", ja: "すべてのメッセージにすぐ返信する必要はないよ。" },
      { id: "c4", text: "I’m worried that I’ll check it without thinking.", ja: "何も考えずに確認してしまいそうで心配だよ。" },
      { id: "c5", text: "I hope you sleep better tonight.", ja: "今夜はよく眠れるといいね。" },
      { id: "c6", text: "You could listen to some quiet music on your phone.", ja: "スマートフォンで静かな音楽を聴くこともできるよ。" }
    ],
    answers: { a: "c1", b: "c3", c: "c2", d: "c4", e: "c5" }
  },

  {
    id: 5, category: "travel", title: "A Trip to Kyoto",
    dialogue: [
      { speaker: "Ken", text: "Hi, Sophie. Have you made any plans for your trip to Kyoto?", ja: "こんにちは、ソフィー。京都旅行の予定は何か立てた？" },
      { speaker: "Sophie", text: "I’ve booked a hotel, but I haven’t decided what places to visit.", ja: "ホテルは予約したけれど、どこを訪れるかはまだ決めていないの。" },
      { speaker: "Ken", blank: "a" },
      { speaker: "Sophie", text: "I’ll be there for three days.", ja: "3日間滞在する予定よ。" },
      { speaker: "Ken", text: "Then you should have enough time to see several famous places.", ja: "それなら、いくつかの有名な場所を見るのに十分な時間があるね。" },
      { speaker: "Sophie", text: "I’d like to visit some temples, but I also want to experience something local.", ja: "お寺をいくつか訪れたいけれど、地元らしいことも体験したいの。" },
      { speaker: "Ken", blank: "b" },
      { speaker: "Ken", text: "There are some small shops and traditional houses there.", ja: "そこには小さなお店や伝統的な家屋がいくつかあるよ。" },
      { speaker: "Sophie", text: "That sounds interesting. Is it far from the station?", ja: "おもしろそうね。駅から遠いの？" },
      { speaker: "Ken", text: "Not very far, but the buses can be crowded during the day.", ja: "それほど遠くはないけれど、昼間はバスが混雑することがあるよ。" },
      { speaker: "Sophie", blank: "c" },
      { speaker: "Ken", text: "Yes. If the weather is nice, renting a bicycle would be convenient.", ja: "うん。天気がよければ、自転車を借りると便利だよ。" },
      { speaker: "Sophie", text: "Good idea. I’ll check whether my hotel rents bicycles.", ja: "いい考えね。ホテルで自転車を貸しているか確認してみるわ。" },
      { speaker: "Ken", text: "Also, try to visit popular temples early in the morning.", ja: "それから、人気のあるお寺には早朝に行くといいよ。" },
      { speaker: "Sophie", text: "Why?", ja: "どうして？" },
      { speaker: "Ken", blank: "d" },
      { speaker: "Ken", text: "You’ll be able to enjoy them more quietly.", ja: "もっと静かに楽しむことができるよ。" },
      { speaker: "Sophie", text: "I see. I’ll get up early, then.", ja: "なるほど。それなら早起きするわ。" },
      { speaker: "Ken", text: "Great.", ja: "いいね。" },
      { speaker: "Ken", blank: "e" },
      { speaker: "Sophie", text: "Thanks, Ken. I’m sure it will be a wonderful trip.", ja: "ありがとう、ケン。きっとすばらしい旅行になると思うわ。" }
    ],
    choices: [
      { id: "c1", text: "How long are you going to stay?", ja: "どれくらい滞在する予定なの？" },
      { id: "c2", text: "I hope you have a great time in Kyoto.", ja: "京都で楽しい時間を過ごせるといいね。" },
      { id: "c3", text: "Would it be easier to travel around by bicycle?", ja: "自転車で移動するほうが簡単かな。" },
      { id: "c4", text: "Why don’t you walk around one of the older neighborhoods?", ja: "古い町並みが残る地域の1つを歩いてみたらどう？" },
      { id: "c5", text: "They are usually less crowded at that time.", ja: "その時間帯は、たいていそれほど混雑していないよ。" },
      { id: "c6", text: "The train from the airport takes about an hour.", ja: "空港からの電車は1時間ほどかかるよ。" }
    ],
    answers: { a: "c1", b: "c4", c: "c3", d: "c5", e: "c2" }
  },

  {
    id: 6, category: "daily", title: "Preparing Dinner",
    dialogue: [
      { speaker: "Mother", text: "Hi, Yuki. I’m going to be home late this evening.", ja: "こんにちは、ユキ。今晩は帰宅が遅くなるの。" },
      { speaker: "Yuki", text: "Really?", ja: "本当？" },
      { speaker: "Yuki", blank: "a" },
      { speaker: "Mother", text: "I have to attend a meeting after work. It may not finish until seven.", ja: "仕事の後に会議に出席しなければならないの。7時まで終わらないかもしれないわ。" },
      { speaker: "Yuki", text: "I see. What should we do about dinner?", ja: "そうなんだ。夕食はどうしたらいい？" },
      { speaker: "Mother", text: "There are some vegetables and chicken in the refrigerator.", ja: "冷蔵庫に野菜と鶏肉があるわ。" },
      { speaker: "Mother", blank: "b" },
      { speaker: "Yuki", text: "I’ve never made it by myself before.", ja: "一人で作ったことは一度もないよ。" },
      { speaker: "Mother", text: "Don’t worry. The recipe is on the kitchen table, and it’s quite simple.", ja: "心配しないで。レシピは台所のテーブルにあるし、とても簡単よ。" },
      { speaker: "Yuki", text: "All right.", ja: "分かった。" },
      { speaker: "Yuki", blank: "c" },
      { speaker: "Mother", text: "Your brother should be home by six. You can ask him to cut the vegetables.", ja: "弟は6時までには帰宅するはずよ。野菜を切るよう頼めるわ。" },
      { speaker: "Yuki", text: "That would make things easier. Do we have enough rice?", ja: "そうすれば楽になるね。お米は十分にある？" },
      { speaker: "Mother", text: "I’m not sure.", ja: "よく分からないわ。" },
      { speaker: "Mother", blank: "d" },
      { speaker: "Yuki", text: "OK. I’ll check it when I get home.", ja: "分かった。帰宅したら確認するよ。" },
      { speaker: "Mother", text: "Thanks, Yuki. I’m sorry to leave everything to you.", ja: "ありがとう、ユキ。全部あなたに任せてごめんね。" },
      { speaker: "Yuki", text: "That’s all right.", ja: "大丈夫だよ。" },
      { speaker: "Yuki", blank: "e" },
      { speaker: "Mother", text: "Thank you. I’ll try not to be too late.", ja: "ありがとう。あまり遅くならないようにするわ。" }
    ],
    choices: [
      { id: "c1", text: "Why don’t you make chicken curry for dinner?", ja: "夕食にチキンカレーを作ったらどう？" },
      { id: "c2", text: "Could you check how much is left?", ja: "どれくらい残っているか確認してくれる？" },
      { id: "c3", text: "Is something wrong?", ja: "何かあったの？" },
      { id: "c4", text: "Do you think my brother can help me?", ja: "弟にも手伝ってもらえると思う？" },
      { id: "c5", text: "We’ll save some dinner for you.", ja: "お母さんの分の夕食を残しておくよ。" },
      { id: "c6", text: "Why don’t we order some food from a restaurant?", ja: "レストランから何か料理を注文したらどう？" }
    ],
    answers: { a: "c3", b: "c1", c: "c4", d: "c2", e: "c5" }
  },

  {
    id: 7, category: "school", title: "Finding a Practice Gym",
    dialogue: [
      { speaker: "Hana", text: "Hi, Mark. Have you heard about the problem with the gym?", ja: "こんにちは、マーク。体育館の問題について聞いた？" },
      { speaker: "Mark", text: "No.", ja: "いいや。" },
      { speaker: "Mark", blank: "a" },
      { speaker: "Hana", text: "The floor is going to be repaired next week, so we can’t practice there.", ja: "来週、床を修理する予定だから、そこで練習できないの。" },
      { speaker: "Mark", text: "That’s a problem. We have an important basketball game at the end of the month.", ja: "それは困ったね。月末に大切なバスケットボールの試合があるのに。" },
      { speaker: "Hana", text: "I know. Our coach asked me to find another place to practice.", ja: "そうなの。コーチから、別の練習場所を探すように頼まれたの。" },
      { speaker: "Mark", blank: "b" },
      { speaker: "Hana", text: "I called them this morning, but another team has already reserved it.", ja: "今朝電話したけれど、別のチームがすでに予約していたわ。" },
      { speaker: "Mark", text: "What about the outdoor court in Central Park?", ja: "中央公園の屋外コートはどう？" },
      { speaker: "Hana", text: "We could use it, but the weather forecast says it may rain.", ja: "使うことはできるけれど、天気予報では雨が降るかもしれないと言っているわ。" },
      { speaker: "Mark", text: "That’s true.", ja: "そうだね。" },
      { speaker: "Mark", blank: "c" },
      { speaker: "Hana", text: "Good idea. Their gym is usually empty after five.", ja: "いい考えね。そこの体育館は、たいてい5時以降は空いているわ。" },
      { speaker: "Mark", text: "Do you know anyone at that school?", ja: "その学校に知り合いはいる？" },
      { speaker: "Hana", text: "Yes. My cousin is a student there.", ja: "いるわ。いとこがそこに通っているの。" },
      { speaker: "Hana", blank: "d" },
      { speaker: "Mark", text: "Great. We should find out as soon as possible.", ja: "よかった。できるだけ早く確認したほうがいいね。" },
      { speaker: "Hana", text: "I’ll call her this evening.", ja: "今晩、いとこに電話するわ。" },
      { speaker: "Mark", text: "Thanks.", ja: "ありがとう。" },
      { speaker: "Mark", blank: "e" },
      { speaker: "Hana", text: "Me too. Missing a week of practice would be difficult for us.", ja: "私もそう願っているわ。1週間練習できないのは、私たちには厳しいからね。" }
    ],
    choices: [
      { id: "c1", text: "Why don’t we ask East High School?", ja: "東高校にお願いしてみたらどう？" },
      { id: "c2", text: "What happened to it?", ja: "体育館に何があったの？" },
      { id: "c3", text: "I hope they let us use the gym.", ja: "体育館を使わせてもらえるといいね。" },
      { id: "c4", text: "Have you contacted the community sports center?", ja: "地域のスポーツセンターには連絡した？" },
      { id: "c5", text: "She may be able to speak to a teacher for us.", ja: "いとこが私たちのために先生に話してくれるかもしれないわ。" },
      { id: "c6", text: "We could practice for a shorter time each day.", ja: "毎日の練習時間を短くすることもできるね。" }
    ],
    answers: { a: "c2", b: "c4", c: "c1", d: "c5", e: "c3" }
  },

  {
    id: 8, category: "service", title: "Ordering at a Restaurant",
    dialogue: [
      { speaker: "Server", text: "Good evening. Are you ready to order?", ja: "こんばんは。ご注文はお決まりですか。" },
      { speaker: "Customer", text: "Almost. Could I ask you something first?", ja: "もう少しです。先に1つ尋ねてもいいですか。" },
      { speaker: "Server", text: "Of course.", ja: "もちろんです。" },
      { speaker: "Server", blank: "a" },
      { speaker: "Customer", text: "Does the vegetable pasta contain any cheese?", ja: "野菜パスタにはチーズが入っていますか。" },
      { speaker: "Server", text: "Yes. It usually comes with cheese on top.", ja: "はい。通常は上にチーズを載せてお出しします。" },
      { speaker: "Customer", text: "I see. I can’t eat dairy products.", ja: "そうですか。私は乳製品を食べることができません。" },
      { speaker: "Server", text: "No problem.", ja: "問題ありません。" },
      { speaker: "Server", blank: "b" },
      { speaker: "Customer", text: "That would be great. I’d like the vegetable pasta, then.", ja: "それは助かります。それでは、野菜パスタをお願いします。" },
      { speaker: "Server", text: "Certainly. Would you like soup or salad with that?", ja: "かしこまりました。スープかサラダをお付けしますか。" },
      { speaker: "Customer", text: "I’ll have the salad, please. Also, could I change the dressing?", ja: "サラダをお願いします。それから、ドレッシングを変更できますか。" },
      { speaker: "Server", text: "Yes. We have lemon, tomato, and herb dressing.", ja: "はい。レモン、トマト、ハーブのドレッシングがございます。" },
      { speaker: "Customer", blank: "c" },
      { speaker: "Server", text: "Certainly. Would you like anything to drink?", ja: "かしこまりました。お飲み物はいかがですか。" },
      { speaker: "Customer", text: "Just water, please.", ja: "水だけでお願いします。" },
      { speaker: "Server", text: "All right.", ja: "承知しました。" },
      { speaker: "Server", blank: "d" },
      { speaker: "Customer", text: "Actually, my friend will be arriving in about ten minutes. Could you wait before bringing the food?", ja: "実は、友人が10分ほどで到着します。料理を運ぶのを待っていただけますか。" },
      { speaker: "Server", text: "Of course.", ja: "もちろんです。" },
      { speaker: "Server", blank: "e" },
      { speaker: "Customer", text: "Thank you. I appreciate that.", ja: "ありがとうございます。助かります。" }
    ],
    choices: [
      { id: "c1", text: "Which dressing would you like?", ja: "どのドレッシングになさいますか。" },
      { id: "c2", text: "What would you like to know?", ja: "何をお知りになりたいですか。" },
      { id: "c3", text: "I’ll ask the cook not to add any cheese.", ja: "料理人にチーズを加えないよう頼みます。" },
      { id: "c4", text: "I’ll bring your order when your friend arrives.", ja: "ご友人が到着したら、ご注文の料理をお持ちします。" },
      { id: "c5", text: "I’ll place your order right away.", ja: "すぐにご注文を厨房へ伝えます。" },
      { id: "c6", text: "The herb dressing sounds good.", ja: "ハーブドレッシングがよさそうです。" }
    ],
    answers: { a: "c2", b: "c3", c: "c6", d: "c5", e: "c4" }
  },

  {
    id: 9, category: "business", title: "Changing a Meeting Time",
    dialogue: [
      { speaker: "Mr. Green", text: "Hi, Laura. Do you have a moment to discuss Friday’s meeting?", ja: "こんにちは、ローラ。金曜日の会議について話す時間はありますか。" },
      { speaker: "Laura", text: "Certainly.", ja: "もちろんです。" },
      { speaker: "Laura", blank: "a" },
      { speaker: "Mr. Green", text: "Two members of the sales team will be visiting a client that morning.", ja: "営業チームの2人が、その日の午前中に顧客を訪問することになりました。" },
      { speaker: "Laura", text: "I see. Are you thinking of changing the time?", ja: "分かりました。時間を変更しようと考えているのですか。" },
      { speaker: "Mr. Green", text: "Yes.", ja: "はい。" },
      { speaker: "Mr. Green", blank: "b" },
      { speaker: "Laura", text: "Let me check my schedule. I have another meeting from two to three, but I’m free after that.", ja: "予定を確認します。2時から3時まで別の会議がありますが、その後は空いています。" },
      { speaker: "Mr. Green", text: "Could we start at three thirty?", ja: "3時30分に始められますか。" },
      { speaker: "Laura", text: "That works for me. However, we also need to check whether the conference room is available.", ja: "私は大丈夫です。ただし、会議室が空いているかも確認する必要があります。" },
      { speaker: "Mr. Green", text: "You’re right.", ja: "そのとおりですね。" },
      { speaker: "Mr. Green", blank: "c" },
      { speaker: "Laura", text: "Thanks. If it’s already reserved, we could use the smaller room on the third floor.", ja: "ありがとうございます。すでに予約されていたら、3階の小さい部屋を使うこともできます。" },
      { speaker: "Mr. Green", text: "That should be large enough. Only eight people are attending.", ja: "そこでも十分な広さでしょう。出席者は8人だけです。" },
      { speaker: "Laura", text: "Shall I send everyone an email about the change?", ja: "変更について、全員にメールを送りましょうか。" },
      { speaker: "Mr. Green", blank: "d" },
      { speaker: "Mr. Green", text: "Please include the new time and possible room change.", ja: "新しい時間と、部屋が変更になる可能性について記載してください。" },
      { speaker: "Laura", text: "No problem. I’ll send it before noon.", ja: "分かりました。正午までに送ります。" },
      { speaker: "Mr. Green", text: "Excellent.", ja: "すばらしい。" },
      { speaker: "Mr. Green", blank: "e" },
      { speaker: "Laura", text: "You’re welcome. I hope the new time is convenient for everyone.", ja: "どういたしまして。新しい時間が全員に都合がよいといいですね。" }
    ],
    choices: [
      { id: "c1", text: "Would Friday afternoon be possible for you?", ja: "金曜日の午後は都合がよいですか。" },
      { id: "c2", text: "What would you like to change?", ja: "何を変更したいのですか。" },
      { id: "c3", text: "I’ll contact the front desk and ask.", ja: "フロントに連絡して尋ねます。" },
      { id: "c4", text: "Yes, that would be very helpful.", ja: "はい、そうしてもらえると非常に助かります。" },
      { id: "c5", text: "Thank you for taking care of it.", ja: "対応してくれてありがとうございます。" },
      { id: "c6", text: "Could we invite more people to the meeting?", ja: "会議にもっと多くの人を招待できますか。" }
    ],
    answers: { a: "c2", b: "c1", c: "c3", d: "c4", e: "c5" }
  },

  {
    id: 10, category: "environment", title: "Reducing Plastic Waste",
    dialogue: [
      { speaker: "Mai", text: "Hi, Carlos. Are you going to the community meeting tonight?", ja: "こんにちは、カルロス。今晩の地域集会に行く予定？" },
      { speaker: "Carlos", text: "I haven’t decided yet.", ja: "まだ決めていないんだ。" },
      { speaker: "Carlos", blank: "a" },
      { speaker: "Mai", text: "The town wants to reduce the amount of plastic waste produced by local stores.", ja: "町は、地域の店から出るプラスチックごみの量を減らしたいと考えているの。" },
      { speaker: "Carlos", text: "That sounds important. What kinds of ideas will they discuss?", ja: "それは大切そうだね。どのような案について話し合うの？" },
      { speaker: "Mai", text: "One idea is to ask stores to stop giving customers free plastic bags.", ja: "1つの案は、店が客に無料のレジ袋を渡すのをやめるよう求めることよ。" },
      { speaker: "Carlos", blank: "b" },
      { speaker: "Carlos", text: "Some people may forget to bring their own bags.", ja: "自分の袋を持ってくるのを忘れる人もいるかもしれないよ。" },
      { speaker: "Mai", text: "That’s true. The town is also considering giving away reusable bags for the first month.", ja: "そうね。町は最初の1か月間、再利用できる袋を無料で配ることも検討しているの。" },
      { speaker: "Carlos", text: "That might encourage people to change their habits.", ja: "それなら、人々が習慣を変えるきっかけになるかもしれないね。" },
      { speaker: "Mai", text: "Exactly.", ja: "そのとおり。" },
      { speaker: "Mai", blank: "c" },
      { speaker: "Carlos", text: "Yes. Restaurants use a large number of plastic containers.", ja: "うん。レストランでは大量のプラスチック容器が使われているからね。" },
      { speaker: "Mai", text: "They may ask restaurants to use paper containers instead.", ja: "町はレストランに、代わりに紙の容器を使うよう求めるかもしれないわ。" },
      { speaker: "Carlos", text: "Paper containers can cost more, though.", ja: "でも、紙の容器は費用が高くなる可能性があるよ。" },
      { speaker: "Mai", text: "That is one of the problems.", ja: "それが問題の1つなの。" },
      { speaker: "Mai", blank: "d" },
      { speaker: "Carlos", text: "Perhaps the town could help small businesses pay part of the extra cost.", ja: "町が、小規模な店に追加費用の一部を支払うのを手助けできるかもしれないね。" },
      { speaker: "Mai", text: "That’s a good suggestion. You should share it at the meeting.", ja: "それはよい提案ね。集会で意見を出したほうがいいよ。" },
      { speaker: "Carlos", text: "All right.", ja: "分かった。" },
      { speaker: "Carlos", blank: "e" },
      { speaker: "Mai", text: "Great. The meeting starts at seven in the community center.", ja: "よかった。集会は地域センターで7時から始まるよ。" }
    ],
    choices: [
      { id: "c1", text: "What is the meeting about?", ja: "その集会では何について話すの？" },
      { id: "c2", text: "However, the town needs to consider the effect on local businesses.", ja: "しかし、町は地域の事業者への影響を考える必要がある。" },
      { id: "c3", text: "I think I’ll attend after all.", ja: "やはり参加することにするよ。" },
      { id: "c4", text: "Do you think they’ll also talk about food containers?", ja: "食品用の容器についても話し合うと思う？" },
      { id: "c5", text: "I’m not sure everyone will support that idea.", ja: "全員がその案に賛成するかは分からないよ。" },
      { id: "c6", text: "How many local stores use plastic bags now?", ja: "現在、地域の店のうち何店舗がレジ袋を使っているの？" }
    ],
    answers: { a: "c1", b: "c5", c: "c4", d: "c2", e: "c3" }
  }
];

const dialogueQuestions11to20 = [
{"id":11,"category":"shopping","title":"Buying a Backpack","dialogue":[{"speaker":"Sales clerk","text":"Good afternoon. May I help you?","ja":"こんにちは。何かお探しですか。"},{"speaker":"Emma","text":"Yes, please. I’m looking for a backpack for my younger brother.","ja":"はい。弟のためのリュックサックを探しています。"},{"speaker":"Sales clerk","text":"Certainly.","ja":"かしこまりました。"},{"speaker":"Sales clerk","blank":"a"},{"speaker":"Emma","text":"He uses it for school every day, so it needs to be strong. He also carries a laptop.","ja":"弟は毎日学校で使うので、丈夫である必要があります。それに、ノートパソコンも持ち運びます。"},{"speaker":"Sales clerk","text":"In that case, this model may be suitable. It has a separate space for a laptop.","ja":"それでしたら、こちらの商品が適しているかもしれません。ノートパソコン専用の収納場所があります。"},{"speaker":"Emma","text":"That looks useful.","ja":"便利そうですね。"},{"speaker":"Emma","blank":"b"},{"speaker":"Sales clerk","text":"It’s eighty dollars, but it is on sale today for sixty-five.","ja":"80ドルですが、本日はセール中なので65ドルです。"},{"speaker":"Emma","text":"That’s within my budget. Does it come in any other colors?","ja":"それなら予算内です。ほかの色もありますか。"},{"speaker":"Sales clerk","text":"Yes. We have it in black, blue, and dark green.","ja":"はい。黒、青、濃い緑がございます。"},{"speaker":"Emma","text":"My brother usually prefers blue.","ja":"弟は普段、青を好みます。"},{"speaker":"Emma","blank":"c"},{"speaker":"Sales clerk","text":"Of course. I’ll get one from the back.","ja":"もちろんです。奥から持ってまいります。"},{"speaker":"Emma","text":"Thank you.","ja":"ありがとうございます。"},{"speaker":"Sales clerk","text":"Here you are. Would you like him to try it on before you buy it?","ja":"こちらです。購入前に、弟さんに背負ってもらいますか。"},{"speaker":"Emma","text":"He isn’t with me today.","ja":"今日は一緒に来ていません。"},{"speaker":"Emma","blank":"d"},{"speaker":"Sales clerk","text":"Certainly. Please keep the receipt, and you can return it within fourteen days.","ja":"もちろんです。レシートを保管していただければ、14日以内に返品できます。"},{"speaker":"Emma","text":"That’s good to know. I’ll take it.","ja":"それを聞いて安心しました。これを買います。"},{"speaker":"Sales clerk","text":"Great.","ja":"ありがとうございます。"},{"speaker":"Sales clerk","blank":"e"},{"speaker":"Emma","text":"By credit card, please.","ja":"クレジットカードでお願いします。"}],"choices":[{"id":"c1","text":"How would you like to pay?","ja":"お支払い方法はいかがなさいますか。"},{"id":"c2","text":"Could I see the blue one?","ja":"青色のものを見せてもらえますか。"},{"id":"c3","text":"How much does it cost?","ja":"いくらですか。"},{"id":"c4","text":"What will he mainly use it for?","ja":"弟さんは主に何のために使いますか。"},{"id":"c5","text":"Could I return it if it doesn’t fit him?","ja":"弟に合わなければ返品できますか。"},{"id":"c6","text":"Does this backpack have any pockets on the outside?","ja":"このリュックには外側にポケットがありますか。"}],"answers":{"a":"c4","b":"c3","c":"c2","d":"c5","e":"c1"}},
{"id":12,"category":"school","title":"Choosing a University Program","dialogue":[{"speaker":"Mr. Hill","text":"Hi, Naomi. Have you decided what you want to study after high school?","ja":"こんにちは、ナオミ。高校卒業後に何を学びたいか決めましたか。"},{"speaker":"Naomi","text":"Not completely. I’m interested in both business and environmental issues.","ja":"完全には決めていません。経営と環境問題の両方に興味があります。"},{"speaker":"Mr. Hill","text":"I see.","ja":"なるほど。"},{"speaker":"Mr. Hill","blank":"a"},{"speaker":"Naomi","text":"I enjoy learning how companies develop new products. However, I also want to help solve environmental problems.","ja":"企業がどのように新商品を開発するかを学ぶのが好きです。でも、環境問題の解決にも役立ちたいと思っています。"},{"speaker":"Mr. Hill","text":"Those interests can be connected. Some universities offer courses in sustainable business.","ja":"その2つの興味は結び付けられます。持続可能な経営について学べる大学もあります。"},{"speaker":"Naomi","text":"I’ve heard that term before, but I’m not sure what it means.","ja":"その言葉は以前に聞いたことがありますが、意味はよく分かりません。"},{"speaker":"Mr. Hill","text":"It is about running a business while reducing harm to the environment.","ja":"環境への悪影響を減らしながら事業を運営することです。"},{"speaker":"Naomi","blank":"b"},{"speaker":"Naomi","text":"I didn’t know I could study both subjects together.","ja":"その2つの分野を一緒に学べるとは知りませんでした。"},{"speaker":"Mr. Hill","text":"You could research universities that offer such programs.","ja":"そのようなプログラムを提供している大学を調べるとよいでしょう。"},{"speaker":"Naomi","text":"I will. Do you think I should attend some university open days?","ja":"そうします。大学のオープンキャンパスにも参加したほうがいいと思いますか。"},{"speaker":"Mr. Hill","text":"Definitely.","ja":"もちろんです。"},{"speaker":"Mr. Hill","blank":"c"},{"speaker":"Naomi","text":"That would help me compare the programs.","ja":"そうすれば、プログラムを比較するのに役立ちますね。"},{"speaker":"Mr. Hill","text":"You should also speak to current students if you have the chance.","ja":"機会があれば、在学生にも話を聞いたほうがいいですよ。"},{"speaker":"Naomi","text":"Why is that?","ja":"どうしてですか。"},{"speaker":"Mr. Hill","blank":"d"},{"speaker":"Mr. Hill","text":"They can tell you what the classes are really like.","ja":"授業が実際にどのようなものか教えてくれます。"},{"speaker":"Naomi","text":"That makes sense. I’ll start checking university websites tonight.","ja":"なるほど。今晩から大学のウェブサイトを確認します。"},{"speaker":"Mr. Hill","text":"Good.","ja":"いいですね。"},{"speaker":"Mr. Hill","blank":"e"},{"speaker":"Naomi","text":"Thank you. I feel more confident about what to do next.","ja":"ありがとうございます。次に何をすべきか、少し自信が持てました。"}],"choices":[{"id":"c1","text":"That sounds exactly like what I’m looking for.","ja":"それはまさに私が探しているもののようです。"},{"id":"c2","text":"What attracts you to those two areas?","ja":"その2つの分野のどのような点にひかれているのですか。"},{"id":"c3","text":"I hope you find a program that suits you.","ja":"あなたに合ったプログラムが見つかるといいですね。"},{"id":"c4","text":"You can attend classes and talk with teachers there.","ja":"そこで授業に参加したり、先生と話したりできます。"},{"id":"c5","text":"They can give you information that is not always in the brochures.","ja":"パンフレットには必ずしも載っていない情報を教えてくれます。"},{"id":"c6","text":"You may also want to compare the cost of each university.","ja":"それぞれの大学にかかる費用も比較したほうがよいかもしれません。"}],"answers":{"a":"c2","b":"c1","c":"c4","d":"c5","e":"c3"}},
{"id":13,"category":"travel","title":"A Delayed Train","dialogue":[{"speaker":"David","text":"Excuse me. Is this the right platform for the train to Lakeside?","ja":"すみません。レイクサイド行きの電車は、このホームで合っていますか。"},{"speaker":"Station worker","text":"Yes, it is, but there has been a change to the schedule.","ja":"はい。ただし、時刻表に変更がありました。"},{"speaker":"David","blank":"a"},{"speaker":"Station worker","text":"The ten fifteen train has been delayed by about forty minutes.","ja":"10時15分発の電車は、約40分遅れています。"},{"speaker":"David","text":"Oh, no. I have an appointment in Lakeside at eleven thirty.","ja":"それは困りました。11時30分にレイクサイドで約束があるのです。"},{"speaker":"Station worker","text":"In that case, you may want to take the express train from Platform Four.","ja":"それでしたら、4番ホームから出る急行列車を利用したほうがよいかもしれません。"},{"speaker":"David","blank":"b"},{"speaker":"Station worker","text":"It leaves in ten minutes and arrives at Lakeside at eleven ten.","ja":"10分後に出発し、11時10分にレイクサイドへ到着します。"},{"speaker":"David","text":"That would be much better. Do I need a different ticket?","ja":"そのほうがずっとよいです。別の切符が必要ですか。"},{"speaker":"Station worker","text":"Yes, there is a small additional charge for the express train.","ja":"はい。急行列車には少し追加料金がかかります。"},{"speaker":"David","blank":"c"},{"speaker":"Station worker","text":"You can pay at the ticket machine near the stairs.","ja":"階段の近くにある券売機で支払えます。"},{"speaker":"David","text":"All right. Is Platform Four far from here?","ja":"分かりました。4番ホームはここから遠いですか。"},{"speaker":"Station worker","text":"No. Go down these stairs and turn left.","ja":"いいえ。この階段を下りて、左に曲がってください。"},{"speaker":"David","text":"Thank you.","ja":"ありがとうございます。"},{"speaker":"David","blank":"d"},{"speaker":"Station worker","text":"You should have enough time if you go now.","ja":"今すぐ行けば、十分間に合うはずです。"},{"speaker":"David","text":"I’ll hurry, then.","ja":"それでは急ぎます。"},{"speaker":"Station worker","text":"Good.","ja":"はい。"},{"speaker":"Station worker","blank":"e"},{"speaker":"David","text":"Thanks for your help.","ja":"ご親切にありがとうございました。"}],"choices":[{"id":"c1","text":"Where can I pay the extra charge?","ja":"追加料金はどこで支払えますか。"},{"id":"c2","text":"What time does the express train arrive?","ja":"急行列車は何時に到着しますか。"},{"id":"c3","text":"I hope you make it to your appointment on time.","ja":"約束の時間に間に合うといいですね。"},{"id":"c4","text":"Will I be able to catch it?","ja":"その電車に間に合いますか。"},{"id":"c5","text":"What kind of change has been made?","ja":"どのような変更があったのですか。"},{"id":"c6","text":"Is there another train later this afternoon?","ja":"今日の午後、後の時間に別の電車はありますか。"}],"answers":{"a":"c5","b":"c2","c":"c1","d":"c4","e":"c3"}},
{"id":14,"category":"daily","title":"Practicing the Guitar","dialogue":[{"speaker":"Lisa","text":"Hi, Tom. Are you still taking guitar lessons?","ja":"こんにちは、トム。今もギターのレッスンを受けているの？"},{"speaker":"Tom","text":"Yes. I’ve been taking them for about six months now.","ja":"うん。もう半年ほど続けているよ。"},{"speaker":"Lisa","blank":"a"},{"speaker":"Tom","text":"I’m improving, but changing chords quickly is still difficult for me.","ja":"上達しているけれど、コードを素早く変えるのはまだ難しいよ。"},{"speaker":"Lisa","text":"Do you practice every day?","ja":"毎日練習しているの？"},{"speaker":"Tom","text":"Almost every day, but usually for only fifteen minutes.","ja":"ほとんど毎日しているけれど、たいてい15分だけなんだ。"},{"speaker":"Lisa","text":"Maybe you should practice a little longer.","ja":"もう少し長く練習したほうがいいかもしれないね。"},{"speaker":"Tom","text":"I’d like to, but I often get bored when I repeat the same song.","ja":"そうしたいけれど、同じ曲を繰り返すと、よく退屈してしまうんだ。"},{"speaker":"Lisa","blank":"b"},{"speaker":"Lisa","text":"You could choose several short songs and practice a different one each day.","ja":"短い曲をいくつか選んで、毎日違う曲を練習することもできるよ。"},{"speaker":"Tom","text":"That might make practice more interesting.","ja":"そうすれば、練習がもっとおもしろくなるかもしれないね。"},{"speaker":"Lisa","text":"Are you preparing for a concert or anything?","ja":"コンサートか何かに向けて準備しているの？"},{"speaker":"Tom","text":"Actually, my teacher wants me to perform at a small concert next month.","ja":"実は、先生が来月の小さなコンサートで演奏してほしいと言っているんだ。"},{"speaker":"Lisa","text":"Really?","ja":"本当？"},{"speaker":"Lisa","blank":"c"},{"speaker":"Tom","text":"I’m excited, but I’m also nervous about playing in front of people.","ja":"楽しみだけれど、人前で演奏するのは緊張もするよ。"},{"speaker":"Lisa","text":"That’s natural. You could practice in front of your family first.","ja":"それは当然だよ。まず家族の前で練習してみたら。"},{"speaker":"Tom","blank":"d"},{"speaker":"Tom","text":"It would help me get used to having an audience.","ja":"観客がいることに慣れるのに役立ちそうだね。"},{"speaker":"Lisa","text":"Exactly. And don’t worry if you make a small mistake.","ja":"そのとおり。それに、小さな間違いをしても心配しないで。"},{"speaker":"Tom","text":"I’ll try to remember that.","ja":"覚えておくよ。"},{"speaker":"Lisa","text":"Good luck with the concert.","ja":"コンサート、頑張ってね。"},{"speaker":"Lisa","blank":"e"},{"speaker":"Tom","text":"Thanks. I’ll invite you when the date is decided.","ja":"ありがとう。日程が決まったら招待するよ。"}],"choices":[{"id":"c1","text":"How are your lessons going?","ja":"レッスンはどう？"},{"id":"c2","text":"Why don’t you add more variety to your practice?","ja":"練習にもっと変化を加えてみたらどう？"},{"id":"c3","text":"I’d love to come and listen.","ja":"ぜひ聴きに行きたいな。"},{"id":"c4","text":"That sounds like a good way to prepare.","ja":"それはよい準備方法のようだね。"},{"id":"c5","text":"How do you feel about performing?","ja":"人前で演奏することをどう感じているの？"},{"id":"c6","text":"Have you thought about buying a different guitar?","ja":"別のギターを買うことを考えたことはある？"}],"answers":{"a":"c1","b":"c2","c":"c5","d":"c4","e":"c3"}},
{"id":15,"category":"technology","title":"Uploading a Presentation Video","dialogue":[{"speaker":"Megan","text":"Hi, Koji. Have you finished preparing your presentation?","ja":"こんにちは、コウジ。発表の準備は終わった？"},{"speaker":"Koji","text":"Almost, but I’m having trouble with the video I want to use.","ja":"ほとんど終わったけれど、使いたい動画で困っているんだ。"},{"speaker":"Megan","blank":"a"},{"speaker":"Koji","text":"The file is too large to upload to the school’s website.","ja":"ファイルが大きすぎて、学校のウェブサイトにアップロードできないんだ。"},{"speaker":"Megan","text":"Have you tried making the video shorter?","ja":"動画を短くしてみた？"},{"speaker":"Koji","text":"Yes, but I need all of it to explain the experiment clearly.","ja":"うん。でも、実験を分かりやすく説明するには全部必要なんだ。"},{"speaker":"Megan","text":"In that case, you could reduce the video quality a little.","ja":"それなら、動画の画質を少し下げることができるよ。"},{"speaker":"Koji","blank":"b"},{"speaker":"Megan","text":"The picture may not be as clear, but the file will become much smaller.","ja":"映像はそれほど鮮明ではなくなるかもしれないけれど、ファイルはずっと小さくなるよ。"},{"speaker":"Koji","text":"That could work. Do you know how to change the quality?","ja":"それならうまくいくかもしれない。画質を変更する方法を知っている？"},{"speaker":"Megan","text":"Yes.","ja":"うん。"},{"speaker":"Megan","blank":"c"},{"speaker":"Koji","text":"Thanks. I’m not very familiar with video-editing software.","ja":"ありがとう。動画編集ソフトにはあまり慣れていないんだ。"},{"speaker":"Megan","text":"It’s easier than it looks. First, open the settings and choose a smaller file size.","ja":"見た目より簡単だよ。まず設定を開いて、小さいファイルサイズを選ぶの。"},{"speaker":"Koji","text":"All right. I’ll try it now.","ja":"分かった。今やってみるよ。"},{"speaker":"Megan","text":"Make sure you keep the original file, though.","ja":"でも、元のファイルは必ず残しておいてね。"},{"speaker":"Koji","text":"Why?","ja":"どうして？"},{"speaker":"Megan","blank":"d"},{"speaker":"Megan","text":"You may need the better-quality version later.","ja":"後で画質のよいほうが必要になるかもしれないから。"},{"speaker":"Koji","text":"Good point. I’ll save a copy before changing anything.","ja":"確かに。何かを変更する前にコピーを保存しておくよ。"},{"speaker":"Megan","text":"Great.","ja":"いいね。"},{"speaker":"Megan","blank":"e"},{"speaker":"Koji","text":"Thank you. That’s a big help.","ja":"ありがとう。とても助かるよ。"}],"choices":[{"id":"c1","text":"What kind of problem are you having?","ja":"どのような問題が起きているの？"},{"id":"c2","text":"I can show you how to do it.","ja":"やり方を教えてあげるよ。"},{"id":"c3","text":"How will that affect the video?","ja":"そうすると動画にどのような影響があるの？"},{"id":"c4","text":"It’s always safer to keep the original.","ja":"元のファイルを残しておくほうがいつでも安全だよ。"},{"id":"c5","text":"Let me know if you still can’t upload it.","ja":"それでもアップロードできなければ教えてね。"},{"id":"c6","text":"Could you upload the video from a different computer?","ja":"別のパソコンから動画をアップロードできる？"}],"answers":{"a":"c1","b":"c3","c":"c2","d":"c4","e":"c5"}},
{"id":16,"category":"family","title":"Helping Grandmother Move","dialogue":[{"speaker":"Father","text":"Hi, Mei. Are you busy this Saturday?","ja":"こんにちは、メイ。今週の土曜日は忙しい？"},{"speaker":"Mei","text":"Not really. Why?","ja":"それほどでもないよ。どうして？"},{"speaker":"Father","text":"Your grandmother is moving some furniture in her house.","ja":"おばあちゃんが家の家具をいくつか動かすんだ。"},{"speaker":"Father","blank":"a"},{"speaker":"Mei","text":"Of course. What does she need us to do?","ja":"もちろん。どんなことを手伝えばいいの？"},{"speaker":"Father","text":"She wants to move a bookshelf from the living room to the guest room.","ja":"居間にある本棚を客間へ移したいそうだよ。"},{"speaker":"Mei","text":"That sounds heavy.","ja":"重そうだね。"},{"speaker":"Mei","blank":"b"},{"speaker":"Father","text":"Yes. Your uncle will come, too, so there will be enough people.","ja":"うん。おじさんも来るから、人手は十分にあるよ。"},{"speaker":"Mei","text":"Good. What time should we go?","ja":"よかった。何時に行けばいい？"},{"speaker":"Father","text":"I told her we would arrive around ten in the morning.","ja":"午前10時ごろに到着すると伝えてあるよ。"},{"speaker":"Mei","text":"All right. Should we bring any tools?","ja":"分かった。何か道具を持っていったほうがいい？"},{"speaker":"Father","blank":"c"},{"speaker":"Father","text":"She said she has a small cart, but some work gloves would be useful.","ja":"小さな台車は持っているそうだけれど、作業用の手袋があると便利だね。"},{"speaker":"Mei","text":"I have a pair in the garage. I’ll bring them.","ja":"車庫に一組あるよ。持っていくね。"},{"speaker":"Father","text":"Thanks. Your grandmother also plans to make lunch for us.","ja":"ありがとう。おばあちゃんは、私たちのために昼食も作る予定なんだ。"},{"speaker":"Mei","text":"She doesn’t have to do that.","ja":"そんなことまでしなくていいよ。"},{"speaker":"Mei","blank":"d"},{"speaker":"Father","text":"I agree. We can pick something up on the way.","ja":"そうだね。途中で何か買っていけるよ。"},{"speaker":"Mei","text":"That would save her some work.","ja":"そうすれば、おばあちゃんの仕事を減らせるね。"},{"speaker":"Father","text":"Good idea.","ja":"いい考えだ。"},{"speaker":"Father","blank":"e"},{"speaker":"Mei","text":"Me too. I haven’t seen her for a few weeks.","ja":"私も。ここ数週間、会っていなかったから。"}],"choices":[{"id":"c1","text":"I’m looking forward to spending time with her.","ja":"おばあちゃんと一緒に過ごすのが楽しみだよ。"},{"id":"c2","text":"Could you come and help us?","ja":"一緒に来て手伝ってくれる？"},{"id":"c3","text":"Maybe we should bring lunch instead.","ja":"代わりに私たちが昼食を持っていったほうがいいかもしれないね。"},{"id":"c4","text":"Will anyone else be there?","ja":"ほかにも誰か来るの？"},{"id":"c5","text":"I think we should buy her a new bookshelf.","ja":"おばあちゃんに新しい本棚を買ったほうがいいと思う。"},{"id":"c6","text":"I already asked her about that.","ja":"そのことは、もうおばあちゃんに聞いたよ。"}],"answers":{"a":"c2","b":"c4","c":"c6","d":"c3","e":"c1"}},
{"id":17,"category":"school","title":"Finding Speech Contest Volunteers","dialogue":[{"speaker":"Mr. Evans","text":"Hi, Rina. How is the preparation for the school speech contest going?","ja":"こんにちは、リナ。校内スピーチコンテストの準備はどうですか。"},{"speaker":"Rina","text":"We’ve chosen the speakers, but we still need more student volunteers.","ja":"発表者は選びましたが、まだ生徒ボランティアがもっと必要です。"},{"speaker":"Mr. Evans","blank":"a"},{"speaker":"Rina","text":"We need students to guide visitors, control the lights, and prepare the stage.","ja":"来場者の案内、照明の操作、舞台の準備をする生徒が必要です。"},{"speaker":"Mr. Evans","text":"Have you asked the members of the student council?","ja":"生徒会のメンバーには頼みましたか。"},{"speaker":"Rina","text":"Yes, but many of them are helping with another school event that day.","ja":"はい。でも、その日は多くの生徒が別の学校行事を手伝っています。"},{"speaker":"Mr. Evans","text":"I see.","ja":"なるほど。"},{"speaker":"Mr. Evans","blank":"b"},{"speaker":"Rina","text":"That might work. Some first-year students may be interested in helping.","ja":"それならうまくいくかもしれません。1年生の中にも、手伝いたい生徒がいるかもしれません。"},{"speaker":"Mr. Evans","text":"You should explain that they don’t need any special experience.","ja":"特別な経験は必要ないと説明したほうがいいですよ。"},{"speaker":"Rina","text":"You’re right. Some students may think the jobs are too difficult.","ja":"そうですね。仕事が難しすぎると思う生徒もいるかもしれません。"},{"speaker":"Mr. Evans","text":"When is the contest?","ja":"コンテストはいつですか。"},{"speaker":"Rina","text":"It’s two weeks from Friday.","ja":"再来週の金曜日です。"},{"speaker":"Mr. Evans","text":"Then you still have some time.","ja":"それなら、まだ少し時間がありますね。"},{"speaker":"Mr. Evans","blank":"c"},{"speaker":"Rina","text":"Good idea. I can make one this afternoon and put it near the entrance.","ja":"いい考えです。今日の午後に作って、玄関の近くに掲示できます。"},{"speaker":"Mr. Evans","text":"Be sure to include the meeting time and the jobs that need to be done.","ja":"集合時間と、必要な仕事内容を必ず書いてください。"},{"speaker":"Rina","text":"I will.","ja":"そうします。"},{"speaker":"Rina","blank":"d"},{"speaker":"Mr. Evans","text":"Probably about fifteen. It would be better to have a few extra people.","ja":"おそらく15人ほどです。少し多めにいたほうがよいでしょう。"},{"speaker":"Rina","text":"All right. I’ll write that we are looking for around eighteen volunteers.","ja":"分かりました。18人ほど募集していると書きます。"},{"speaker":"Mr. Evans","text":"Excellent.","ja":"すばらしい。"},{"speaker":"Mr. Evans","blank":"e"},{"speaker":"Rina","text":"Thank you. I’ll let you know how many students sign up.","ja":"ありがとうございます。何人申し込んだかお知らせします。"}],"choices":[{"id":"c1","text":"Why don’t you make a notice for the school bulletin board?","ja":"学校の掲示板に募集のお知らせを作ったらどうですか。"},{"id":"c2","text":"What kind of help do you need?","ja":"どのような手伝いが必要なのですか。"},{"id":"c3","text":"How many volunteers will be necessary?","ja":"ボランティアは何人必要ですか。"},{"id":"c4","text":"I’m sure you’ll find enough people.","ja":"きっと十分な人数が集まりますよ。"},{"id":"c5","text":"Could we reduce the number of jobs for volunteers?","ja":"ボランティアの仕事内容を減らすことはできますか。"},{"id":"c6","text":"How about inviting students from other grades?","ja":"ほかの学年の生徒にも声をかけてみてはどうですか。"}],"answers":{"a":"c2","b":"c6","c":"c1","d":"c3","e":"c4"}},
{"id":18,"category":"travel","title":"Joining a River Cruise","dialogue":[{"speaker":"Tourist","text":"Excuse me. I’d like to join the river cruise this afternoon.","ja":"すみません。今日の午後、川のクルーズに参加したいのですが。"},{"speaker":"Guide","text":"Certainly.","ja":"かしこまりました。"},{"speaker":"Guide","blank":"a"},{"speaker":"Tourist","text":"Just one, please. What time does the next boat leave?","ja":"1枚お願いします。次の船は何時に出ますか。"},{"speaker":"Guide","text":"It leaves at two thirty, so you have about forty minutes.","ja":"2時30分に出発するので、あと40分ほどあります。"},{"speaker":"Tourist","text":"Great. How long does the cruise take?","ja":"よかったです。クルーズはどれくらいかかりますか。"},{"speaker":"Guide","text":"About ninety minutes. It goes past several historic buildings and an old bridge.","ja":"約90分です。いくつかの歴史的な建物や古い橋のそばを通ります。"},{"speaker":"Tourist","text":"That sounds interesting.","ja":"おもしろそうですね。"},{"speaker":"Tourist","blank":"b"},{"speaker":"Guide","text":"Yes. The guide gives explanations in English and Japanese.","ja":"はい。ガイドが英語と日本語で説明します。"},{"speaker":"Tourist","text":"Good. Is there anywhere to sit inside the boat?","ja":"よかったです。船内に座れる場所はありますか。"},{"speaker":"Guide","text":"There is a small indoor area, but most of the seats are outside.","ja":"小さな屋内スペースがありますが、ほとんどの座席は外にあります。"},{"speaker":"Tourist","text":"I see. It looks like it might rain later.","ja":"そうですか。後で雨が降りそうですね。"},{"speaker":"Guide","blank":"c"},{"speaker":"Guide","text":"We also lend umbrellas to passengers if necessary.","ja":"必要であれば、乗客に傘もお貸ししています。"},{"speaker":"Tourist","text":"That’s helpful. Can I bring food onto the boat?","ja":"それは助かります。船に食べ物を持ち込めますか。"},{"speaker":"Guide","text":"Drinks are allowed, but we ask passengers not to eat during the cruise.","ja":"飲み物は持ち込めますが、クルーズ中の食事はご遠慮いただいています。"},{"speaker":"Tourist","text":"No problem.","ja":"分かりました。"},{"speaker":"Tourist","blank":"d"},{"speaker":"Guide","text":"The ticket office is beside the entrance to the pier.","ja":"チケット売り場は船着き場の入口の横にあります。"},{"speaker":"Tourist","text":"Thank you. I’ll buy my ticket now.","ja":"ありがとうございます。今からチケットを買います。"},{"speaker":"Guide","text":"You’re welcome.","ja":"どういたしまして。"},{"speaker":"Guide","blank":"e"},{"speaker":"Tourist","text":"Thanks. I’m looking forward to it.","ja":"ありがとうございます。楽しみにしています。"}],"choices":[{"id":"c1","text":"How many tickets would you like?","ja":"チケットは何枚必要ですか。"},{"id":"c2","text":"Does someone explain the sights during the trip?","ja":"クルーズ中に、誰かが景色について説明してくれますか。"},{"id":"c3","text":"Where should I buy the ticket?","ja":"チケットはどこで買えばよいですか。"},{"id":"c4","text":"I hope you enjoy the cruise.","ja":"クルーズを楽しんでください。"},{"id":"c5","text":"The boat has a roof over part of the seating area.","ja":"座席の一部には屋根があります。"},{"id":"c6","text":"Is there a discount for children under twelve?","ja":"12歳未満の子どもには割引がありますか。"}],"answers":{"a":"c1","b":"c2","c":"c5","d":"c3","e":"c4"}},
{"id":19,"category":"work","title":"Changing a Work Shift","dialogue":[{"speaker":"Manager","text":"Hi, Jason. You said you wanted to discuss your work schedule.","ja":"こんにちは、ジェイソン。勤務予定について話したいと言っていましたね。"},{"speaker":"Jason","text":"Yes.","ja":"はい。"},{"speaker":"Jason","blank":"a"},{"speaker":"Manager","text":"I see. Is it difficult for you to work on Tuesday evenings?","ja":"分かりました。火曜日の夜に働くのが難しいのですか。"},{"speaker":"Jason","text":"Yes. I’ve started taking an evening class, and it begins at six.","ja":"はい。夜間講座に通い始めたのですが、6時に始まります。"},{"speaker":"Manager","text":"How often do you attend the class?","ja":"その講座にはどれくらいの頻度で通うのですか。"},{"speaker":"Jason","text":"Once a week for the next three months.","ja":"今後3か月間、週に1回です。"},{"speaker":"Manager","text":"All right.","ja":"分かりました。"},{"speaker":"Manager","blank":"b"},{"speaker":"Jason","text":"I could work on Thursday evening instead.","ja":"代わりに木曜日の夜なら働けます。"},{"speaker":"Manager","text":"That may be possible. However, Maria usually works on Thursdays.","ja":"可能かもしれません。ただし、木曜日は通常マリアが勤務しています。"},{"speaker":"Jason","text":"I could ask whether she would be willing to exchange shifts with me.","ja":"彼女に勤務を交換してもらえるか聞いてみます。"},{"speaker":"Manager","text":"Good idea.","ja":"いいですね。"},{"speaker":"Manager","blank":"c"},{"speaker":"Jason","text":"I’ll speak to her during our lunch break today.","ja":"今日の昼休みに彼女と話します。"},{"speaker":"Manager","text":"Please make sure she is comfortable with the change.","ja":"彼女がその変更に納得していることを必ず確認してください。"},{"speaker":"Jason","text":"Of course. If she agrees, should we fill out a schedule-change form?","ja":"もちろんです。彼女が同意したら、勤務変更届に記入すればよいですか。"},{"speaker":"Manager","text":"Yes.","ja":"はい。"},{"speaker":"Manager","blank":"d"},{"speaker":"Jason","text":"All right. I’ll bring it to you tomorrow morning.","ja":"分かりました。明日の朝、持ってきます。"},{"speaker":"Manager","text":"Thank you for handling this responsibly.","ja":"責任をもって対応してくれてありがとうございます。"},{"speaker":"Jason","text":"I appreciate your understanding.","ja":"ご理解いただきありがとうございます。"},{"speaker":"Manager","text":"You’re welcome.","ja":"どういたしまして。"},{"speaker":"Manager","blank":"e"},{"speaker":"Jason","text":"Thank you. I’ll let you know what Maria says.","ja":"ありがとうございます。マリアが何と言ったかお知らせします。"}],"choices":[{"id":"c1","text":"Let me know after you have spoken with her.","ja":"彼女と話した後で知らせてください。"},{"id":"c2","text":"What other evening could you work?","ja":"ほかのどの曜日の夜なら働けますか。"},{"id":"c3","text":"I’d like to change one of my weekly shifts.","ja":"毎週の勤務のうち1回を変更したいです。"},{"id":"c4","text":"Both of you will need to sign it.","ja":"あなたとマリアの両方が署名する必要があります。"},{"id":"c5","text":"I hope your evening class goes well.","ja":"夜間講座がうまくいくといいですね。"},{"id":"c6","text":"Could Maria work an extra hour on Thursday?","ja":"木曜日にマリアが1時間余分に働くことはできますか。"}],"answers":{"a":"c3","b":"c2","c":"c1","d":"c4","e":"c5"}},
{"id":20,"category":"health","title":"Shoulder Pain","dialogue":[{"speaker":"Nurse","text":"Good morning. What brings you in today?","ja":"おはようございます。今日はどうされましたか。"},{"speaker":"Paul","text":"I’ve had pain in my right shoulder for about a week.","ja":"1週間ほど、右肩が痛むのです。"},{"speaker":"Nurse","blank":"a"},{"speaker":"Paul","text":"I first noticed it after playing tennis last Saturday.","ja":"先週の土曜日にテニスをした後、初めて痛みに気付きました。"},{"speaker":"Nurse","text":"Did you fall or hit your shoulder during the game?","ja":"試合中に転んだり、肩をぶつけたりしましたか。"},{"speaker":"Paul","text":"No, but I played for almost four hours without taking a break.","ja":"いいえ。でも、休憩を取らずに4時間近くプレーしました。"},{"speaker":"Nurse","text":"I see. Does it hurt all the time?","ja":"分かりました。ずっと痛みますか。"},{"speaker":"Paul","text":"Not when I’m resting.","ja":"休んでいるときは痛くありません。"},{"speaker":"Paul","blank":"b"},{"speaker":"Nurse","text":"Have you tried putting ice on it?","ja":"氷で冷やしてみましたか。"},{"speaker":"Paul","text":"Yes, and it helped a little.","ja":"はい。少し楽になりました。"},{"speaker":"Nurse","text":"The doctor will examine you shortly. Until then, try not to move your arm too much.","ja":"まもなく医師が診察します。それまでは、腕をあまり動かさないようにしてください。"},{"speaker":"Paul","text":"All right. Do you think it could be serious?","ja":"分かりました。深刻なものだと思いますか。"},{"speaker":"Nurse","text":"It may only be a strained muscle, but the doctor will need to check.","ja":"単なる筋肉の損傷かもしれませんが、医師が確認する必要があります。"},{"speaker":"Paul","blank":"c"},{"speaker":"Nurse","text":"Probably not, but you should avoid tennis until the pain is gone.","ja":"おそらくその必要はありませんが、痛みがなくなるまではテニスを控えたほうがよいでしょう。"},{"speaker":"Paul","text":"I understand. Is there anything else I should do?","ja":"分かりました。ほかに何かしたほうがよいことはありますか。"},{"speaker":"Nurse","blank":"d"},{"speaker":"Nurse","text":"Also, be careful not to carry anything heavy.","ja":"また、重い物を持たないように気を付けてください。"},{"speaker":"Paul","text":"I’ll follow that advice.","ja":"その助言に従います。"},{"speaker":"Nurse","text":"Good. The doctor is ready to see you now.","ja":"分かりました。先生の診察の準備ができました。"},{"speaker":"Paul","text":"Thank you.","ja":"ありがとうございます。"},{"speaker":"Nurse","text":"You’re welcome.","ja":"どういたしまして。"},{"speaker":"Nurse","blank":"e"}],"choices":[{"id":"c1","text":"When did the pain begin?","ja":"痛みはいつ始まりましたか。"},{"id":"c2","text":"It hurts when I lift my arm.","ja":"腕を上げると痛みます。"},{"id":"c3","text":"Will I need to stop exercising completely?","ja":"運動を完全にやめる必要がありますか。"},{"id":"c4","text":"Continue using ice for short periods.","ja":"短い時間ずつ氷で冷やし続けてください。"},{"id":"c5","text":"Please go through the door on your left.","ja":"左側のドアからお入りください。"},{"id":"c6","text":"Have you ever injured your left shoulder before?","ja":"以前、左肩を痛めたことはありますか。"}],"answers":{"a":"c1","b":"c2","c":"c3","d":"c4","e":"c5"}}
];

const dialogueQuestions21to30 = [
{"id":21,"category":"daily","title":"Two Plans at the Same Time","dialogue":[{"speaker":"Aya","text":"Hi, Ben. You seem a little worried.","ja":"こんにちは、ベン。少し心配そうだね。"},{"speaker":"Ben","text":"I am. I promised to help Chris move this Saturday, but I completely forgot about my sister’s birthday lunch.","ja":"そうなんだ。今週の土曜日にクリスの引っ越しを手伝うと約束したんだけど、姉の誕生日の昼食会をすっかり忘れていたんだ。"},{"speaker":"Aya","blank":"a"},{"speaker":"Ben","text":"They are both at almost the same time.","ja":"どちらもほとんど同じ時間なんだ。"},{"speaker":"Aya","text":"Have you explained the situation to Chris?","ja":"そのことをクリスに説明した？"},{"speaker":"Ben","text":"Not yet. I’m afraid he’ll be disappointed.","ja":"まだなんだ。がっかりさせるのが心配で。"},{"speaker":"Aya","text":"He may understand if you tell him honestly.","ja":"正直に話せば、分かってくれるかもしれないよ。"},{"speaker":"Ben","text":"You’re probably right.","ja":"たぶんそうだね。"},{"speaker":"Ben","blank":"b"},{"speaker":"Aya","text":"Could you help him in the morning and join your family later?","ja":"午前中に彼を手伝って、その後で家族と合流することはできない？"},{"speaker":"Ben","text":"That might be possible. Chris said he wanted to start early.","ja":"それなら可能かもしれない。クリスは早く始めたいと言っていたんだ。"},{"speaker":"Aya","text":"Then ask him what time he needs you.","ja":"それなら、何時に来てほしいか聞いてみたら。"},{"speaker":"Ben","text":"I will. If that doesn’t work, I could help him on Sunday instead.","ja":"そうするよ。それが無理なら、代わりに日曜日に手伝うこともできる。"},{"speaker":"Aya","blank":"c"},{"speaker":"Ben","text":"Yes. He has several other friends helping, so one day’s difference may not matter.","ja":"うん。ほかにも何人かの友人が手伝うから、1日の違いはそれほど問題にならないかもしれない。"},{"speaker":"Aya","text":"Exactly. The important thing is to contact him as soon as possible.","ja":"そのとおり。大切なのは、できるだけ早く連絡することだよ。"},{"speaker":"Ben","text":"I’ll call him after class.","ja":"授業の後で電話するよ。"},{"speaker":"Aya","text":"Good.","ja":"いいね。"},{"speaker":"Aya","blank":"d"},{"speaker":"Ben","text":"I hope so. I don’t want either of them to think I don’t care.","ja":"そうだといいな。どちらにも、自分が大切に思っていないとは思われたくないんだ。"},{"speaker":"Aya","text":"I’m sure they know you do.","ja":"きっと、あなたが大切に思っていることは分かっているよ。"},{"speaker":"Ben","text":"Thanks for listening.","ja":"話を聞いてくれてありがとう。"},{"speaker":"Aya","text":"You’re welcome.","ja":"どういたしまして。"},{"speaker":"Aya","blank":"e"}],"choices":[{"id":"c1","text":"Perhaps you can find a way to do both.","ja":"両方できる方法を見つけられるかもしれないよ。"},{"id":"c2","text":"That sounds like another reasonable solution.","ja":"それも妥当な解決方法のようだね。"},{"id":"c3","text":"I hope everything works out.","ja":"すべてうまくいくといいね。"},{"id":"c4","text":"What is causing the problem?","ja":"何が問題になっているの？"},{"id":"c5","text":"It’s better than waiting until the last minute.","ja":"最後の瞬間まで待つよりよいよ。"},{"id":"c6","text":"Could your sister change the time of the lunch?","ja":"お姉さんは昼食会の時間を変えられないの？"}],"answers":{"a":"c4","b":"c1","c":"c2","d":"c5","e":"c3"}},
{"id":22,"category":"school","title":"Improving Vocabulary Study","dialogue":[{"speaker":"Mr. Lewis","text":"Hi, Saki. How did you do on the last English vocabulary test?","ja":"こんにちは、サキ。この前の英単語テストはどうでしたか。"},{"speaker":"Saki","text":"Not very well. I studied the night before, but I forgot many of the words during the test.","ja":"あまりよくありませんでした。前日の夜に勉強したのですが、テスト中に多くの単語を忘れてしまいました。"},{"speaker":"Mr. Lewis","blank":"a"},{"speaker":"Saki","text":"Usually only once or twice before each test.","ja":"普段は、それぞれのテストの前に1回か2回だけです。"},{"speaker":"Mr. Lewis","text":"That may be the problem. It is difficult to remember many words after studying them only once.","ja":"それが問題かもしれません。一度しか勉強していない多くの単語を覚えるのは難しいです。"},{"speaker":"Saki","text":"I know. What should I do differently?","ja":"分かっています。どのように変えればよいですか。"},{"speaker":"Mr. Lewis","text":"Try reviewing a small number of words every day.","ja":"毎日、少しずつ単語を復習してみてください。"},{"speaker":"Saki","blank":"b"},{"speaker":"Mr. Lewis","text":"Even ten or fifteen minutes can make a difference if you do it regularly.","ja":"定期的に続ければ、10分か15分でも効果があります。"},{"speaker":"Saki","text":"I could study on the bus in the morning.","ja":"朝、バスの中で勉強できます。"},{"speaker":"Mr. Lewis","text":"That would be a good use of your time.","ja":"それは時間のよい使い方ですね。"},{"speaker":"Saki","text":"Should I just read the word list again and again?","ja":"単語リストを何度も読むだけでよいですか。"},{"speaker":"Mr. Lewis","text":"Not only that.","ja":"それだけではありません。"},{"speaker":"Mr. Lewis","blank":"c"},{"speaker":"Saki","text":"You mean I should try to remember the answer before looking at it?","ja":"答えを見る前に、自分で思い出そうとするということですか。"},{"speaker":"Mr. Lewis","text":"Exactly. That helps you check what you truly know.","ja":"そのとおりです。そうすることで、本当に知っていることを確認できます。"},{"speaker":"Saki","text":"I’ll try using small cards with English on one side and Japanese on the other.","ja":"片面に英語、もう片面に日本語を書いた小さなカードを使ってみます。"},{"speaker":"Mr. Lewis","text":"Good idea.","ja":"いい考えです。"},{"speaker":"Mr. Lewis","blank":"d"},{"speaker":"Saki","text":"All right. I’ll separate the difficult words and review them more often.","ja":"分かりました。難しい単語を分けて、より頻繁に復習します。"},{"speaker":"Mr. Lewis","text":"Excellent.","ja":"すばらしい。"},{"speaker":"Mr. Lewis","blank":"e"},{"speaker":"Saki","text":"Thank you. I’ll start today.","ja":"ありがとうございます。今日から始めます。"}],"choices":[{"id":"c1","text":"How often do you usually review the words?","ja":"普段、どれくらいの頻度で単語を復習していますか。"},{"id":"c2","text":"Focus more on the words you get wrong.","ja":"間違えた単語をより重点的に勉強してください。"},{"id":"c3","text":"I hope your next result improves.","ja":"次の結果がよくなるといいですね。"},{"id":"c4","text":"Is a short amount of study really enough?","ja":"短い勉強時間でも本当に十分なのですか。"},{"id":"c5","text":"Try testing yourself instead of only reading.","ja":"読むだけでなく、自分でテストしてみてください。"},{"id":"c6","text":"You could also write example sentences for some words.","ja":"いくつかの単語について例文を書くこともできます。"}],"answers":{"a":"c1","b":"c4","c":"c5","d":"c2","e":"c3"}},
{"id":23,"category":"service","title":"Trouble with Wireless Earphones","dialogue":[{"speaker":"Customer","text":"Excuse me. I bought these wireless earphones here yesterday, but I’m having a problem with them.","ja":"すみません。昨日ここでこのワイヤレスイヤホンを買ったのですが、問題があります。"},{"speaker":"Clerk","text":"I’m sorry to hear that.","ja":"それは申し訳ございません。"},{"speaker":"Clerk","blank":"a"},{"speaker":"Customer","text":"The left earphone doesn’t produce any sound.","ja":"左側のイヤホンから音が出ません。"},{"speaker":"Clerk","text":"Have you charged both earphones fully?","ja":"両方のイヤホンを十分に充電しましたか。"},{"speaker":"Customer","text":"Yes. I left them in the charging case all night.","ja":"はい。一晩中、充電ケースに入れておきました。"},{"speaker":"Clerk","text":"I see. Sometimes one earphone does not connect correctly to the phone.","ja":"なるほど。片方のイヤホンがスマートフォンに正しく接続されないことがあります。"},{"speaker":"Customer","blank":"b"},{"speaker":"Clerk","text":"First, remove the earphones from your phone’s Bluetooth list. Then connect them again.","ja":"まず、スマートフォンのBluetoothの一覧からイヤホンを削除してください。その後、もう一度接続してください。"},{"speaker":"Customer","text":"All right. Could we try that here?","ja":"分かりました。ここで試してもらえますか。"},{"speaker":"Clerk","text":"Certainly. Please open the Bluetooth settings on your phone.","ja":"もちろんです。スマートフォンのBluetooth設定を開いてください。"},{"speaker":"Customer","text":"Here they are.","ja":"こちらです。"},{"speaker":"Clerk","text":"Thank you. I’ll reset the earphones now.","ja":"ありがとうございます。今からイヤホンをリセットします。"},{"speaker":"Customer","text":"It seems to be working. I can hear sound from both sides.","ja":"動いているようです。両方から音が聞こえます。"},{"speaker":"Clerk","text":"Good.","ja":"よかったです。"},{"speaker":"Clerk","blank":"c"},{"speaker":"Customer","text":"What should I do if the same problem happens again?","ja":"同じ問題がまた起きたら、どうすればよいですか。"},{"speaker":"Clerk","text":"Try resetting them once more. If that doesn’t help, bring them back with your receipt.","ja":"もう一度リセットしてみてください。それでも直らなければ、レシートと一緒にお持ちください。"},{"speaker":"Customer","blank":"d"},{"speaker":"Clerk","text":"Yes. They have a one-year warranty.","ja":"はい。1年間の保証が付いています。"},{"speaker":"Customer","text":"That’s reassuring.","ja":"それなら安心です。"},{"speaker":"Clerk","text":"Please contact us if you have any other trouble.","ja":"ほかに問題があればご連絡ください。"},{"speaker":"Customer","text":"Thank you very much.","ja":"本当にありがとうございました。"},{"speaker":"Clerk","text":"You’re welcome.","ja":"どういたしまして。"},{"speaker":"Clerk","blank":"e"}],"choices":[{"id":"c1","text":"How can I reconnect them?","ja":"どのように再接続すればよいですか。"},{"id":"c2","text":"What exactly is wrong with them?","ja":"具体的にどのような問題がありますか。"},{"id":"c3","text":"They should now connect normally.","ja":"これで正常に接続されるはずです。"},{"id":"c4","text":"Would they be replaced if they were faulty?","ja":"故障していた場合、交換してもらえますか。"},{"id":"c5","text":"I hope you enjoy using them.","ja":"イヤホンを楽しんで使ってください。"},{"id":"c6","text":"Have you tried using the earphones with another device?","ja":"別の機器でそのイヤホンを使ってみましたか。"}],"answers":{"a":"c2","b":"c1","c":"c3","d":"c4","e":"c5"}},
{"id":24,"category":"business","title":"Improving a Customer Survey","dialogue":[{"speaker":"Manager","text":"Hi, Olivia. I saw your message about the customer survey.","ja":"こんにちは、オリビア。顧客アンケートについてのメッセージを見ました。"},{"speaker":"Olivia","text":"Thanks for meeting with me. We received fewer responses than expected.","ja":"お時間をいただきありがとうございます。予想より回答が少なかったのです。"},{"speaker":"Manager","blank":"a"},{"speaker":"Olivia","text":"We sent the survey by email to five hundred customers, but only forty replied.","ja":"500人の顧客にメールでアンケートを送りましたが、回答したのは40人だけでした。"},{"speaker":"Manager","text":"That is quite a low response rate. Was the survey very long?","ja":"かなり低い回答率ですね。アンケートはとても長かったのですか。"},{"speaker":"Olivia","text":"It had twenty-five questions and took about fifteen minutes to complete.","ja":"25問あり、回答に約15分かかりました。"},{"speaker":"Manager","text":"That may have discouraged some people.","ja":"それで答える気をなくした人もいたかもしれませんね。"},{"speaker":"Olivia","text":"I thought so, too.","ja":"私もそう思いました。"},{"speaker":"Olivia","blank":"b"},{"speaker":"Manager","text":"Yes. Ten short questions may be enough to collect the most important information.","ja":"そうですね。最も重要な情報を集めるには、短い質問を10問ほどで十分かもしれません。"},{"speaker":"Olivia","text":"We could also offer customers a small discount for completing it.","ja":"回答してくれた顧客に小さな割引を提供することもできます。"},{"speaker":"Manager","text":"That might increase the number of responses, but we need to consider the cost.","ja":"回答数は増えるかもしれませんが、費用を考える必要があります。"},{"speaker":"Olivia","text":"Of course.","ja":"もちろんです。"},{"speaker":"Olivia","blank":"c"},{"speaker":"Manager","text":"Good idea. Then we can compare the results before sending it to everyone.","ja":"いい考えです。それなら、全員に送る前に結果を比較できます。"},{"speaker":"Olivia","text":"Should we send the new survey by email again?","ja":"新しいアンケートも、もう一度メールで送るべきですか。"},{"speaker":"Manager","text":"Email is fine, but you could also include a link on our website.","ja":"メールでよいですが、ウェブサイトにもリンクを載せられます。"},{"speaker":"Olivia","blank":"d"},{"speaker":"Manager","text":"Exactly. Customers who visit the website may notice it even if they missed the email.","ja":"そのとおりです。メールを見逃した顧客でも、ウェブサイトを訪れれば気付くかもしれません。"},{"speaker":"Olivia","text":"I’ll prepare a shorter version and a test plan by tomorrow.","ja":"明日までに、短いアンケートとテスト計画を準備します。"},{"speaker":"Manager","text":"Excellent.","ja":"すばらしい。"},{"speaker":"Manager","blank":"e"},{"speaker":"Olivia","text":"Thank you. I’ll show you the draft before we send anything.","ja":"ありがとうございます。何かを送る前に、下書きをお見せします。"}],"choices":[{"id":"c1","text":"Why don’t we test the new survey with a small group first?","ja":"まず少人数で新しいアンケートを試してみてはどうですか。"},{"id":"c2","text":"How many customers completed it?","ja":"何人の顧客が回答したのですか。"},{"id":"c3","text":"That would give people another way to find it.","ja":"そうすれば、別の方法でも見つけてもらえます。"},{"id":"c4","text":"I think we should reduce the number of questions.","ja":"質問数を減らしたほうがよいと思います。"},{"id":"c5","text":"Let’s review the results together after the test.","ja":"テスト後に一緒に結果を確認しましょう。"},{"id":"c6","text":"Could we send the survey at a different time of day?","ja":"アンケートを別の時間帯に送ることはできますか。"}],"answers":{"a":"c2","b":"c4","c":"c1","d":"c3","e":"c5"}},
{"id":25,"category":"event","title":"Going to a Summer Festival","dialogue":[{"speaker":"Maya","text":"Hi, Daniel. Are you going to the summer festival in the town square this weekend?","ja":"こんにちは、ダニエル。今週末、町の広場で行われる夏祭りに行く予定？"},{"speaker":"Daniel","text":"I’m thinking about it. I’ve never been to it before.","ja":"行こうか考えているよ。今まで一度も行ったことがないんだ。"},{"speaker":"Maya","blank":"a"},{"speaker":"Daniel","text":"What kinds of events do they have?","ja":"どのような催しがあるの？"},{"speaker":"Maya","text":"There are traditional dances, music performances, and food stands.","ja":"伝統的な踊りや音楽の演奏、それに食べ物の屋台があるよ。"},{"speaker":"Daniel","text":"That sounds fun. Do visitors take part in the dances?","ja":"楽しそうだね。訪れた人も踊りに参加するの？"},{"speaker":"Maya","text":"Yes.","ja":"うん。"},{"speaker":"Maya","blank":"b"},{"speaker":"Daniel","text":"I don’t know any of the steps, though.","ja":"でも、踊り方を全く知らないよ。"},{"speaker":"Maya","text":"That’s not a problem. Volunteers show everyone how to do the basic movements before the dance begins.","ja":"問題ないよ。踊りが始まる前に、ボランティアが基本的な動きをみんなに教えてくれるの。"},{"speaker":"Daniel","text":"In that case, I might try it.","ja":"それなら、やってみようかな。"},{"speaker":"Maya","text":"You should. It’s one of the best parts of the festival.","ja":"ぜひやってみて。祭りの中でも特に楽しいものの1つだよ。"},{"speaker":"Daniel","text":"Is the festival crowded?","ja":"祭りは混雑する？"},{"speaker":"Maya","text":"Very crowded in the evening.","ja":"夕方はとても混雑するよ。"},{"speaker":"Maya","blank":"c"},{"speaker":"Daniel","text":"Good advice. I also want to take some photographs.","ja":"いい助言だね。写真も撮りたいんだ。"},{"speaker":"Maya","text":"Then you may want to go before sunset. The square looks beautiful while it is still light.","ja":"それなら、日が沈む前に行ったほうがいいかもしれないね。まだ明るいうちは、広場がきれいに見えるよ。"},{"speaker":"Daniel","text":"What happens if it rains?","ja":"雨が降ったらどうなるの？"},{"speaker":"Maya","blank":"d"},{"speaker":"Maya","text":"Only very heavy rain would cause it to be canceled.","ja":"とても激しい雨でない限り、中止にはならないよ。"},{"speaker":"Daniel","text":"That’s good. I’ll check the weather forecast on Saturday morning.","ja":"それならよかった。土曜日の朝に天気予報を確認するよ。"},{"speaker":"Maya","text":"Great.","ja":"いいね。"},{"speaker":"Maya","blank":"e"},{"speaker":"Daniel","text":"Thanks. Maybe I’ll see you there.","ja":"ありがとう。会場で会うかもしれないね。"}],"choices":[{"id":"c1","text":"Most activities continue in light rain.","ja":"小雨なら、ほとんどの催しは続けられるよ。"},{"id":"c2","text":"You should arrive early if you want a good place to stand.","ja":"よい場所で見たいなら、早めに着いたほうがいいよ。"},{"id":"c3","text":"I think you would enjoy it.","ja":"あなたも楽しめると思うよ。"},{"id":"c4","text":"Anyone can join if they want to.","ja":"希望すれば誰でも参加できるよ。"},{"id":"c5","text":"Let me know whether you decide to come.","ja":"来ることに決めたかどうか教えてね。"},{"id":"c6","text":"Are there any places to sit near the food stands?","ja":"食べ物の屋台の近くに座る場所はある？"}],"answers":{"a":"c3","b":"c4","c":"c2","d":"c1","e":"c5"}},
{"id":26,"category":"travel","title":"A Missing Suitcase","dialogue":[{"speaker":"Traveler","text":"Excuse me. My suitcase hasn’t come out yet.","ja":"すみません。私のスーツケースがまだ出てこないのですが。"},{"speaker":"Airport staff","text":"I’m sorry to hear that.","ja":"それは申し訳ございません。"},{"speaker":"Airport staff","blank":"a"},{"speaker":"Traveler","text":"I arrived on Flight 305 from Singapore.","ja":"シンガポール発305便で到着しました。"},{"speaker":"Airport staff","text":"Thank you. Did you check in one suitcase?","ja":"ありがとうございます。スーツケースを1つ預けましたか。"},{"speaker":"Traveler","text":"Yes. It’s a large gray suitcase with a red ribbon on the handle.","ja":"はい。持ち手に赤いリボンが付いた、大きな灰色のスーツケースです。"},{"speaker":"Airport staff","text":"I see. Could I look at your baggage claim ticket?","ja":"分かりました。手荷物引換証を見せていただけますか。"},{"speaker":"Traveler","text":"Of course. Here it is.","ja":"もちろんです。こちらです。"},{"speaker":"Airport staff","text":"Thank you. According to our system, your suitcase was placed on a later flight by mistake.","ja":"ありがとうございます。システムによると、お客様のスーツケースは間違って後の便に載せられたようです。"},{"speaker":"Traveler","blank":"b"},{"speaker":"Airport staff","text":"It should arrive at about nine this evening.","ja":"今晩9時ごろに到着する予定です。"},{"speaker":"Traveler","text":"I’m staying at a hotel in the city. Do I have to come back to the airport?","ja":"市内のホテルに泊まっています。空港まで戻ってこなければなりませんか。"},{"speaker":"Airport staff","text":"No.","ja":"いいえ。"},{"speaker":"Airport staff","blank":"c"},{"speaker":"Traveler","text":"That would be very helpful. When do you think it will reach the hotel?","ja":"それはとても助かります。ホテルには何時ごろ届くと思いますか。"},{"speaker":"Airport staff","text":"Probably before midnight, but it may take longer if traffic is heavy.","ja":"おそらく深夜までには届きますが、交通が混雑していると、さらに時間がかかるかもしれません。"},{"speaker":"Traveler","text":"I understand. Is there anything I need to fill out?","ja":"分かりました。何か記入する必要がありますか。"},{"speaker":"Airport staff","text":"Yes.","ja":"はい。"},{"speaker":"Airport staff","blank":"d"},{"speaker":"Traveler","text":"All right. I’ll write my hotel name and phone number.","ja":"分かりました。ホテル名と電話番号を書きます。"},{"speaker":"Airport staff","text":"Thank you. We’ll contact you as soon as the suitcase arrives.","ja":"ありがとうございます。スーツケースが到着し次第、ご連絡いたします。"},{"speaker":"Traveler","text":"I appreciate your help.","ja":"ご親切にありがとうございます。"},{"speaker":"Airport staff","text":"You’re welcome.","ja":"どういたしまして。"},{"speaker":"Airport staff","blank":"e"}],"choices":[{"id":"c1","text":"Which flight were you on?","ja":"どの便に乗っていましたか。"},{"id":"c2","text":"We can deliver it to your hotel.","ja":"ホテルまでお届けできます。"},{"id":"c3","text":"Please complete this missing-baggage form.","ja":"この手荷物紛失届にご記入ください。"},{"id":"c4","text":"When is the later flight expected to arrive?","ja":"後の便は何時に到着する予定ですか。"},{"id":"c5","text":"I hope your suitcase reaches you soon.","ja":"スーツケースが早く届くといいですね。"},{"id":"c6","text":"Did you put anything valuable in the suitcase?","ja":"スーツケースの中に貴重品を入れましたか。"}],"answers":{"a":"c1","b":"c4","c":"c2","d":"c3","e":"c5"}},
{"id":27,"category":"school","title":"Improving the School Library","dialogue":[{"speaker":"Ms. Carter","text":"Hi, Taku. I heard the student council wants to improve the school library.","ja":"こんにちは、タク。生徒会が学校図書館を改善したいと考えていると聞きました。"},{"speaker":"Taku","text":"Yes. We asked students what changes they would like to see.","ja":"はい。生徒たちに、どのような変更を希望するか尋ねました。"},{"speaker":"Ms. Carter","blank":"a"},{"speaker":"Taku","text":"Many students want more places where they can study in groups.","ja":"多くの生徒が、グループで勉強できる場所をもっと増やしてほしいと考えています。"},{"speaker":"Ms. Carter","text":"The library is usually expected to be quiet, though.","ja":"でも、図書館は普通、静かにすることが求められますよね。"},{"speaker":"Taku","text":"That’s true. We are thinking of using the small room at the back for group study.","ja":"そのとおりです。奥にある小さな部屋をグループ学習用に使おうと考えています。"},{"speaker":"Ms. Carter","blank":"b"},{"speaker":"Taku","text":"We could put a glass wall around it so that the noise doesn’t disturb other students.","ja":"騒音がほかの生徒の迷惑にならないよう、ガラスの壁で囲むことができます。"},{"speaker":"Ms. Carter","text":"That sounds reasonable. Did students request anything else?","ja":"それならよさそうですね。ほかにも要望はありましたか。"},{"speaker":"Taku","text":"Yes. Some want the library to stay open later before examinations.","ja":"はい。試験前は図書館をもっと遅くまで開けてほしいという意見もありました。"},{"speaker":"Ms. Carter","text":"How late is it open now?","ja":"今は何時まで開いていますか。"},{"speaker":"Taku","text":"It closes at five thirty.","ja":"5時30分に閉まります。"},{"speaker":"Ms. Carter","blank":"c"},{"speaker":"Taku","text":"We would like it to stay open until seven during the two weeks before exams.","ja":"試験前の2週間は、7時まで開けてほしいと考えています。"},{"speaker":"Ms. Carter","text":"You will need teachers or staff members to supervise the library.","ja":"図書館を監督する先生や職員が必要になりますね。"},{"speaker":"Taku","text":"I know.","ja":"分かっています。"},{"speaker":"Taku","blank":"d"},{"speaker":"Ms. Carter","text":"Good. It may be easier if several teachers share the responsibility.","ja":"いいですね。何人かの先生で役割を分担すれば、より実現しやすいかもしれません。"},{"speaker":"Taku","text":"We’ll prepare a detailed plan and present it at the next staff meeting.","ja":"詳しい計画を準備し、次の職員会議で提案します。"},{"speaker":"Ms. Carter","text":"Excellent.","ja":"すばらしい。"},{"speaker":"Ms. Carter","blank":"e"},{"speaker":"Taku","text":"Thank you. I hope the plan will help more students use the library.","ja":"ありがとうございます。その計画で、もっと多くの生徒が図書館を利用するようになるといいです。"}],"choices":[{"id":"c1","text":"What was the most common suggestion?","ja":"最も多かった提案は何ですか。"},{"id":"c2","text":"How will you prevent it from becoming too noisy?","ja":"騒がしくなりすぎないように、どのようにしますか。"},{"id":"c3","text":"What closing time are you suggesting?","ja":"何時に閉館することを提案しているのですか。"},{"id":"c4","text":"We plan to ask for volunteers among the teachers.","ja":"先生方の中からボランティアを募集する予定です。"},{"id":"c5","text":"I look forward to hearing your proposal.","ja":"あなたたちの提案を聞くのを楽しみにしています。"},{"id":"c6","text":"Could the library add more computers for students?","ja":"図書館に生徒用のパソコンをもっと増やせますか。"}],"answers":{"a":"c1","b":"c2","c":"c3","d":"c4","e":"c5"}},
{"id":28,"category":"business","title":"Customer-Service Training","dialogue":[{"speaker":"Supervisor","text":"Hi, Nina. How did the customer-service training go yesterday?","ja":"こんにちは、ニナ。昨日の接客研修はどうでしたか。"},{"speaker":"Nina","text":"It was useful, but some employees found one part difficult.","ja":"役に立ちましたが、一部の社員はある内容を難しいと感じていました。"},{"speaker":"Supervisor","blank":"a"},{"speaker":"Nina","text":"The role-playing activity. They had to respond to customers who were angry about a problem.","ja":"ロールプレイ活動です。問題について怒っている顧客に対応しなければなりませんでした。"},{"speaker":"Supervisor","text":"I see. Were they unsure what to say?","ja":"なるほど。何と言えばよいか分からなかったのですか。"},{"speaker":"Nina","text":"Yes. Some employees tried to explain the company rules immediately.","ja":"はい。何人かの社員は、すぐに会社の規則を説明しようとしていました。"},{"speaker":"Supervisor","text":"That can sometimes make an angry customer even more upset.","ja":"それでは、怒っている顧客をさらに怒らせることがあります。"},{"speaker":"Nina","text":"Exactly. The trainer said we should listen carefully before offering a solution.","ja":"そのとおりです。解決策を提案する前に、注意深く話を聞くべきだと講師が言っていました。"},{"speaker":"Supervisor","blank":"b"},{"speaker":"Nina","text":"Yes. Customers often calm down when they feel that someone understands them.","ja":"はい。誰かが自分のことを理解してくれていると感じると、顧客は落ち着くことが多いです。"},{"speaker":"Supervisor","text":"Did the employees have enough time to practice?","ja":"社員には十分な練習時間がありましたか。"},{"speaker":"Nina","text":"Not really. Each pair only had one chance.","ja":"あまりありませんでした。それぞれのペアは1回しかできませんでした。"},{"speaker":"Supervisor","blank":"c"},{"speaker":"Nina","text":"That’s what I was thinking. We could spend thirty minutes on it at next week’s team meeting.","ja":"私もそう考えていました。来週のチーム会議で30分ほど使えます。"},{"speaker":"Supervisor","text":"Good idea. You could prepare several common situations in advance.","ja":"いい考えです。よくある状況をいくつか事前に準備するとよいでしょう。"},{"speaker":"Nina","text":"I’ll ask employees to work in pairs and change roles.","ja":"社員をペアにして、役割を交代させます。"},{"speaker":"Supervisor","text":"Excellent.","ja":"すばらしい。"},{"speaker":"Supervisor","blank":"d"},{"speaker":"Nina","text":"Yes. Watching others may help them learn different ways to respond.","ja":"はい。ほかの人を見ることで、さまざまな対応方法を学べるかもしれません。"},{"speaker":"Supervisor","text":"Please send me your activity plan by Friday.","ja":"金曜日までに活動計画を送ってください。"},{"speaker":"Nina","text":"I will.","ja":"分かりました。"},{"speaker":"Supervisor","text":"Thank you.","ja":"ありがとう。"},{"speaker":"Supervisor","blank":"e"},{"speaker":"Nina","text":"I hope so, too. Good customer service is important for everyone.","ja":"私もそう願っています。よい接客は全員にとって大切です。"}],"choices":[{"id":"c1","text":"Which part caused the most trouble?","ja":"どの部分が最も難しかったのですか。"},{"id":"c2","text":"That shows why empathy is so important.","ja":"それは、相手の気持ちを理解することがなぜ重要なのかを示していますね。"},{"id":"c3","text":"Perhaps they need another opportunity to practice.","ja":"もう一度練習する機会が必要かもしれません。"},{"id":"c4","text":"You could also let the other employees give feedback.","ja":"ほかの社員にも意見を言ってもらうとよいでしょう。"},{"id":"c5","text":"I hope the extra practice builds their confidence.","ja":"追加の練習で自信がつくといいですね。"},{"id":"c6","text":"Could the employees watch a training video first?","ja":"社員は最初に研修用の動画を見ることもできますか。"}],"answers":{"a":"c1","b":"c2","c":"c3","d":"c4","e":"c5"}},
{"id":29,"category":"community","title":"Taking Part in an Emergency Drill","dialogue":[{"speaker":"Keiko","text":"Hi, Sam. Did you see the notice about the emergency drill?","ja":"こんにちは、サム。防災訓練についてのお知らせを見た？"},{"speaker":"Sam","text":"Yes. It will be held in our neighborhood next Sunday.","ja":"うん。来週の日曜日に、私たちの地域で行われるよ。"},{"speaker":"Keiko","blank":"a"},{"speaker":"Sam","text":"The residents will practice what to do after a large earthquake.","ja":"住民が、大きな地震の後に何をすべきか練習するんだ。"},{"speaker":"Keiko","text":"I’ve never taken part in one before.","ja":"今まで一度も参加したことがないわ。"},{"speaker":"Sam","text":"Neither have I, but I think it will be useful.","ja":"僕もないけれど、役に立つと思うよ。"},{"speaker":"Keiko","text":"What activities are planned?","ja":"どのような活動が予定されているの？"},{"speaker":"Sam","text":"First, we’ll practice moving safely to the local elementary school.","ja":"まず、地域の小学校まで安全に移動する練習をするよ。"},{"speaker":"Keiko","text":"Is that the emergency shelter for our area?","ja":"そこが私たちの地域の避難所なの？"},{"speaker":"Sam","text":"Yes.","ja":"うん。"},{"speaker":"Sam","blank":"b"},{"speaker":"Keiko","text":"That’s important. During a real emergency, some roads may be blocked.","ja":"それは大切ね。本当の災害時には、通れない道路もあるかもしれないから。"},{"speaker":"Sam","text":"Exactly. They will also show us how to use a fire extinguisher.","ja":"そのとおり。それから、消火器の使い方も教えてくれるよ。"},{"speaker":"Keiko","text":"I’d like to learn that. Will we need to bring anything?","ja":"それは学びたいわ。何か持っていく必要はある？"},{"speaker":"Sam","blank":"c"},{"speaker":"Sam","text":"They also recommend wearing comfortable shoes.","ja":"それから、歩きやすい靴を履くよう勧められているよ。"},{"speaker":"Keiko","text":"All right. I’ll take a bottle of water and a small towel.","ja":"分かった。水のボトルと小さなタオルを持っていくわ。"},{"speaker":"Sam","text":"Good idea. The drill begins at nine in the morning.","ja":"いい考えだね。訓練は午前9時に始まるよ。"},{"speaker":"Keiko","text":"How long will it last?","ja":"どれくらい続くの？"},{"speaker":"Sam","text":"About two hours.","ja":"約2時間だよ。"},{"speaker":"Sam","blank":"d"},{"speaker":"Keiko","text":"Then I’ll be able to attend before meeting my friend in the afternoon.","ja":"それなら、午後に友達と会う前に参加できるわ。"},{"speaker":"Sam","text":"Great. Shall we walk there together?","ja":"よかった。一緒に歩いて行こうか。"},{"speaker":"Keiko","text":"Yes, please.","ja":"うん、お願い。"},{"speaker":"Sam","text":"Good.","ja":"よし。"},{"speaker":"Sam","blank":"e"},{"speaker":"Keiko","text":"Me too. It’s better to be prepared before something happens.","ja":"私も。何か起こる前に準備しておくほうがいいものね。"}],"choices":[{"id":"c1","text":"What will we be practicing?","ja":"何を練習するの？"},{"id":"c2","text":"We’ll learn which roads are safest to use.","ja":"どの道路を使うのが最も安全か学ぶよ。"},{"id":"c3","text":"You should bring some water and a hat.","ja":"水と帽子を持っていったほうがいいよ。"},{"id":"c4","text":"It is expected to finish before noon.","ja":"正午までには終わる予定だよ。"},{"id":"c5","text":"I’m glad we’re both taking part.","ja":"2人とも参加することにしてよかったよ。"},{"id":"c6","text":"Will families receive a map of the shelter area?","ja":"各家庭には避難所周辺の地図が配られますか。"}],"answers":{"a":"c1","b":"c2","c":"c3","d":"c4","e":"c5"}},
{"id":30,"category":"health","title":"Starting a Swimming Routine","dialogue":[{"speaker":"Leo","text":"Hi, Sarah. You said you started swimming recently. How is it going?","ja":"こんにちは、サラ。最近水泳を始めたと言っていたね。調子はどう？"},{"speaker":"Sarah","text":"I’m enjoying it, but I get tired very quickly.","ja":"楽しんでいるけれど、すぐに疲れてしまうの。"},{"speaker":"Leo","blank":"a"},{"speaker":"Sarah","text":"Usually twice a week for about thirty minutes.","ja":"たいてい週に2回、30分ほどよ。"},{"speaker":"Leo","text":"That sounds like a reasonable start. Were you exercising regularly before?","ja":"始めたばかりなら、それくらいがちょうどよさそうだね。以前は定期的に運動していたの？"},{"speaker":"Sarah","text":"Not really. I spent most of my free time reading or watching movies.","ja":"あまりしていなかったわ。自由時間のほとんどを、読書や映画を見ることに使っていたの。"},{"speaker":"Leo","text":"Then your body may need time to get used to the exercise.","ja":"それなら、体が運動に慣れるまで時間が必要かもしれないね。"},{"speaker":"Sarah","text":"I suppose so. I sometimes try to swim as fast as possible from the beginning.","ja":"そうかもしれない。時々、最初からできるだけ速く泳ごうとしてしまうの。"},{"speaker":"Leo","blank":"b"},{"speaker":"Leo","text":"You may have more energy if you begin at a comfortable speed.","ja":"楽な速さで始めれば、もっと体力が残るかもしれないよ。"},{"speaker":"Sarah","text":"That makes sense. Should I try to swim for a longer time?","ja":"なるほど。もっと長い時間泳いだほうがいい？"},{"speaker":"Leo","text":"Not yet. First, focus on swimming regularly without becoming too exhausted.","ja":"まだその必要はないよ。まずは疲れすぎないように、定期的に泳ぐことを大切にしたほうがいい。"},{"speaker":"Sarah","blank":"c"},{"speaker":"Leo","text":"Yes. You could add five minutes after a few weeks if you feel comfortable.","ja":"うん。数週間後、余裕があれば5分ずつ増やすことができるよ。"},{"speaker":"Sarah","text":"I’ll do that. I also feel very hungry after swimming.","ja":"そうしてみるわ。それから、水泳の後はとてもおなかがすくの。"},{"speaker":"Leo","text":"Make sure you drink enough water first. People sometimes confuse thirst with hunger.","ja":"まず、十分に水を飲むようにしてね。喉の渇きを空腹だと勘違いすることもあるから。"},{"speaker":"Sarah","text":"I didn’t know that.","ja":"それは知らなかった。"},{"speaker":"Sarah","blank":"d"},{"speaker":"Leo","text":"A light snack is fine, especially if it contains some protein.","ja":"軽いおやつなら大丈夫だよ。特に、たんぱく質が含まれているものがいいね。"},{"speaker":"Sarah","text":"Maybe I’ll have yogurt or a banana.","ja":"ヨーグルトかバナナにしようかな。"},{"speaker":"Leo","text":"Good choices.","ja":"いい選択だね。"},{"speaker":"Leo","blank":"e"},{"speaker":"Sarah","text":"Thanks. I’ll try to improve little by little.","ja":"ありがとう。少しずつ上達できるように頑張るわ。"}],"choices":[{"id":"c1","text":"How often do you go to the pool?","ja":"どれくらいの頻度でプールに行っているの？"},{"id":"c2","text":"You may be starting too quickly.","ja":"最初から速く泳ぎすぎているのかもしれないよ。"},{"id":"c3","text":"So I should increase the time slowly.","ja":"つまり、泳ぐ時間は少しずつ増やせばいいのね。"},{"id":"c4","text":"Is it all right to eat something afterward?","ja":"終わった後に何か食べても大丈夫？"},{"id":"c5","text":"The important thing is to continue.","ja":"大切なのは続けることだよ。"},{"id":"c6","text":"You could try walking on the days you don’t swim.","ja":"泳がない日は、歩いてみることもできるよ。"}],"answers":{"a":"c1","b":"c2","c":"c3","d":"c4","e":"c5"}}
];

dialogueQuestions.push(
  ...dialogueQuestions11to20,
  ...dialogueQuestions21to30
);
